(window.STORIES=window.STORIES||[]).push(...[{"n": 37, "l": "الحلقه ٥٣ | مريم | الحلقه ٥٤ | يحي", "u": "https://www.facebook.com/groups/710210019782034/permalink/760459318090437/", "t": "#قصص_الأنبياء \n#الحلقة_الثالثة_والخمسون\n#مريم_زكريا_الجزء_الثالث\n#مريم_الجزء_الأول\nاتكلمنا المرة إللي فاتت عن زكريا عليه السلام وإنه دعا ربنا إنه يرزقه الذرية الصالحة لما شاف إنه بيرزق مريم بنت عمران فاكهة الصيف في الشتاء وفاكهة الشتاء في الصيف،\nوكان ده كرامة من ربنا لمريم بسبب كثرة عبادتها وزهدها وتعلقها بالله،\nكانت مريم مختلفة عن البنات إللي في سنها، يعني كان جسمها بيكبر وبيقرب من البلوغ أسرع من البنات العادية،\nوكان من عادة بني إسرائيل إنهم يحجّون لبيت المقدس،\nيعني بيطلعوا في قافلة من مدن القدس ويتوجهوا من هناك لبيت المقدس لأن بيت المقدس كان قبلتهم،\nزي ما المسلمين بيتوجهوا للحج في مكة\nفي يوم من الأيام لما كان عمرها حوالي خمسة عشر سنة\nخرجت في قافلة مع أهلها لبيت المقدس وهي كانت من مدينة النّاصرة،\nفي الطريق..سابت أهلها وتأخرت عن القافلة لسبب معين،\n\"إِذِ انتَبَذَتْ مِنْ أَهْلِهَا مَكَانًا شَرْقِيًّا\"\nإيه السبب منعرفش بالضبط..ممكن يكون أصابها الحيض، \nأو إنها كانت عايزة تطهر من الحيض...أو غيرها من أقوال العلماء،\nالمهم إن حصل حاجة خلتها تتأخر عن الناس إللي معاها وراحت وراء جبل قريب كده بس بعيد عن عنيهم،\n\"فَاتَّخَذَتْ مِن دُونِهِمْ حِجَابًا \"\nفهي كانت عايزة تكون لوحدها..وفجأة لقت قصادها رجل..فاتخضت وخافت \n\"فَأَرْسَلْنَا إِلَيْهَا رُوحَنَا فَتَمَثَّلَ لَهَا بَشَرًا سَوِيًّا\"\nفكرت إن الرجل ده عايز يراودها عن نفسها أو عاوز يؤذيها \n ويعمل فيها حاجة يعني،\nفقالت له : أعوذ بالرحمن منك لو كنت من المتقين\nلأن التّقي هو إللي بيخاف ربنا وخوفه من ربنا بيمنعه إنه يعمل أي شيء محرم\n\"قالَتْ إِنِّي أَعُوذُ بِالرَّحْمَن مِنكَ إِن كُنتَ تَقِيًّا\"\nفالرجل قالها: متخافيش الموضوع مش زي مانتي فاكرة أنا رسول من عند ربك عشان أوهبك غلام..طفل طيب وطاهر، هتكوني انتِ أمه.\n\"قَالَ إِنَّمَا أَنَا رَسُولُ رَبِّكِ لِأَهَبَ لَكِ غُلامًا زَكِيًّا\"\n☆قبل ما نكمل هنقف كم وقفة كده مع آيات القرآن نتدبرها \n♡ربنا بيقول 《وأرسلنا إليها روحنا》\nالروح هنا المقصود به جبريل عليه السلام ..طيب ليه ربنا سمّى جبريل عليه السلام بالروح\nاحنا كبشر بنتكون من حاجتين هما جسد وروح صح؟\nإيه إللي بيحرك الجسد\nالروح هي إللي بتحرك الجسد..يعني الروح هي السبب في حياة الجسد\nجبريل عليه السلام هو المَلك المسؤول عن توصيل الوحي،\nوالوحي ده سبب في حياة القلوب...فالإنسان بيكون حي بحاجتين: حياة جسدية وحياة قلبية\nالحياة الجسدية كوووول الناس بتشترك فيها حتى الحيوانات بتشترك في الحياة الجسدية دي،\nلكن الحياة القلبية دي خاصة بعباد الله المتقين....\n\"أَوَمَن كَانَ مَيْتًا فَأَحْيَيْنَاهُ\" يعني كان كافرا فهديناه\nيعني باختصار كده الروح تحيا بها الأجساد وجبريل عليه السلام يحيا بسببه القلوب عن طريق الوحي..عشان كده اسمه الروح\n♡ نشوف الآية الثانية :\nربنا بيقول عن مريم لما راحت في مكان لوحدها لقت قصادها رجل《بشرا سويا》..ليه ربنا قال بشرًا سويا \nعشان يوصّل لنا إن إللي مريم شافته كان من البشر ومكنش من الجن..ده أولاً\nثانيا : البشر إللي هي شافته ده هو في أصله مَلك من الملائكة إللي هو جبريل عليه السلام،\nوالبشر ميقدروش يشوفوا الملائكة على أصلهم لازم يتمثلوا في صورة بشر عشان نقدر نشوفهم،\nفلو كان الرجل إللي هي شافته ده طويل جدا مثلا أو قصير جدا أو في خِلقته أو في شكله أي حاجة مختلفة عن البشر العاديين كان الطبيعي إنها تخاف ويبان إن ده إللي مخوّفها\nلكن القرآن بيقول لنا إن ده مكنش سبب خوفها،\nيعني هي مخفتش لمجرد إنها شافت بشر لإن البشر إللي شافته كان بشر سويّ الخِلقة مفيهوش علامة غريبة تستدعي الخوف في حد ذاته.. لأ.. ده بشر طبيعي زي أي بشر،\nلكن هي خافت على نفسها من الرجل ده إنه يعتدى عليها \n ♡الآية الثالثة\nلما قالت مريم《إني أعوذ بالرحمن منك》 ليه قالت الرحمن؟ مع إن المفروض هنا كانت تقول الجبار أو ذو الانتقام والبطش عشان تخوفه مثلا ، ولإن هي عايزة تدفع عن نفسها الضرر  فطبيعي تستغيث بالقوي المتين الجبار \nزي كده لو حد اعتدى على حقي، هقول له:\n \"موعدنا عند الرحمن\"؟ ولّا هقول له موعدنا  عند الجبار ؟ \nفمريم عليها السلام قالت الرحمن بالذات ومقلتش اسم تاني من أسماء الله الحسنى إللي فيها معنى الاستجارة بذي القوة والجبروت والبطش؛ لإنها  كانت بتحاول تذكّر الراجل ده برحمة ربنا قبل عذابه\nبتذكّره بالرجاء قبل الخوف من باب الرفق بالناس ودعوتهم للخير قبل ترهيبهم بالضر والعقوبة..\n◇وده يعلمنا إن في الدعوة إلى الله قبل ماننهى عن المنكر نأمر الناس بالمعروف حتى ربنا بيقول لنا إيه:\n\"كُنتُمْ خَيْرَ أُمَّةٍ أُخْرِجَتْ لِلنَّاسِ تَأْمُرُونَ بِالْمَعْرُوفِ وَتَنْهَوْنَ عَنِ الْمُنكَرِ \" \nفربنا قدم الأمر بالمعروف قبل النهي عن المنكر\nفدايما في الدعوة إلى الله نقدم الأمر بالمعروف وبعدها على طول في نفس اللحظة ننهى عن المنكر.. مش نلغيه أو نأجله خالص، لأ.. \nهو مجرد ترتيب أسبقية قدر المستطاع وحسب الموقف طبعا، \nيعني بنقدم لهم البديل الصحيح\nومريم رضي الله عنها مكنتش تعرف هل الرجل ده تقي ولّا لأ فعشان كده حطت له شرط من باب التشجيع والتحفيز له..وهو :\n《 إن كنت تقيا》يعني لو انت من إللي بيخافوا ربنا فإنت مش هتؤذيني،\nزي مثلا لما نقول لحد لو انت بتحب ربنا اعمل كذا..فنلاقي الشخص اتحمس: أيوة أنا بحب ربنا ويبدأ يعمل،\nوزي ما ربنا بيقول لنا :\n \" وَأَطِيعُوا اللَّهَ وَرَسُولَهُ إِن كُنتُم مُّؤْمِنِينَ\"\nفتلاقينا بنتحمس لطاعة ربنا ورسوله عشان نكون مؤمنين\n◇في الغالب لو اتكلمنا مع الناس بالمعروف والترغيب الأول الناس هتستجيب\nوزي ما قلنا من شوية ربنا بيقول لنا:\n\"كُنتُمْ خَيْرَ أُمَّةٍ أُخْرِجَتْ لِلنَّاسِ تَأْمُرُونَ بِالْمَعْرُوفِ وَتَنْهَوْنَ عَنِ الْمُنكَرِ \"\n فربنا قدم الأمر بالمعروف قبل النهي عن المنكر\nفمريم عليها السلام ذكّرت الرجل ده برحمة ربنا إنه لو كان ناوي على شر فربنا رحيم هيقبله لو هو معملش المعصية ورجع عن إللي في دماغه، \nمش ساعات كده بييجي في بالنا حاجات غلط عايزين نعملها والشيطان بيقعد يشجعنا ويقولنا خلاص اعمل الغلط ده ماهو ربنا عالم بنيتك السودة دي أصلا ومُطلع على سريرتك السيئة، فهتروح تصلي إزاي دلوقتي وانت كنت ناوي على كذا وبتفكر في كذا وكذا\nفيقعد ييئسنا من رحمة ربنا عشان نرتكب الغلط ونستمر عليه ونعمل غلط تاني أكبر منه وهكذا..\nفالإنسان في اللحظة دي بيبقى محتاج حد يذكّره برحمة ربنا .. انت معملتش حاجة لسه.. ارجع .. ربنا رحيم.. حتى لو كنت عملت.. ربك بيقبل التوبة\n وهكذا.. \nفمريم عليها السلام ذكّرت الرجل ده برحمة ربنا إنه لو كان ناوي على شر فربنا رحيم هيقبله لو هو معملش المعصية ورجع عن إللي في دماغه وكمان هي كان في حالة استضعاف فممكن لو أخدت موقف شديد تستفز الرجل ويعتدي عليها\nنرجع بقى لكلام جبريل عليه السلام وإنه قال لها إنه رسول من عند ربنا، \nالأول بشرها إن ربنا اصطفاها وطهرها على كل نساء الدنيا..\n\"إِذْ قَالَتِ الْمَلائِكَةُ يَا مَرْيَمُ إِنَّ اللَّهَ اصْطَفَاكِ وَطَهَّرَكِ وَاصْطَفَاكِ عَلَى نِسَاء الْعَالَمِينَ\"\nوبعدين قال لها إن ربنا بيبشرك إنه هيوهبك غلام..لكن الغلام ده مختلف ..هو كلمة ربنا ..يعني هيخلقه في رحمك بكلمة كن فيكون..\n\"إذْ قَالَتِ الْمَلائِكَةُ يَا مَرْيَمُ إِنَّ اللَّهَ يُبَشِّرُكِ بِكَلِمَةٍ مِّنْهُ اسْمُهُ الْمَسِيحُ عِيسَى ابْنُ مَرْيَمَ وَجِيهًا فِي الدُّنْيَا وَالآخِرَةِ وَمِنَ الْمُقَرَّبِينَ\"\nوهيكون مشهور في الدنيا وهيتعرف اسمه بين المؤمنين بالمسيح عيسى بن مريم..وله وَجاهة وله مكانة عند ربنا...\nهيكلم الناس ويدعوهم لعبادة الله وهو لسه مولود في المهد وكمان لما يكبر ..وهيكون من الصالحين المقربين عند ربنا\n\"وَيُكَلِّمُ النَّاسَ فِي الْمَهْدِ وَكَهْلاً وَمِنَ الصَّالِحِينَ\"\n☆قبل ما نشوف رد فعل مريم عليها السلام عايزين نرجع كده شوية للوراء في الزمن، ونشوف أصل مريم كان إيه\nأصل مريم كان نية صالحة \nفاكرين لما أمها حنّة تمنّت إن يكون عندها ولد عشان يخدم الدين ويكون عابد لله، وربنا رزقها ببنت وكأنها زعلت إنها مش هتعرف تحقق إللي كان نفسها فيه...ومع ذلك هي استغلت المتاح إللي ربنا أعطاه لها\nالسؤال بقى\nهل أم مريم كانت تتصور يوم ما وضعت البنت إن البنت دي هتكون أفضل نساء العالمين؟\nهل تصورت ولا جه على بالها إن مريم دي هتخلف نبي من أولي العزم من الرسل بمعجزة إلهية محصلتش ومش هتحصل إلى يوم القيامة؟\nهل تصورت حنة إن النبي ده هينسب لبنتها مريم إللي هي من آل عمران؟\n♡وده يعلمنا إننا منستعجلش ومنزعلش لما حاجة عكس إللي احنا عايزينها تحصل \nويعلمنا إن نية الإنسان ممكن في وقت من الأوقات تكون أفضل من عمله\nنرجع بقى لمريم إللي كانت بتسمع كلام جبريل عليه السلام وهي متفاجئة... بشارة ورا التانية..وقبل كل ده ..إزاي هيكون لها طفل أصلا وهي مش متزوجة ومش ناوية تتزوج ولم تفعل الفاحشة\n\"قَالَتْ أَنَّى يَكُونُ لِي غُلامٌ وَلَمْ يَمْسَسْنِي بَشَرٌ وَلَمْ أَكُ بَغِيًّا\"\nفلما قالت للمَلك الكلام ده قال لها:\nهو أمر ربنا خلاص قضاه..هتحملي بطفل بدون رجل عشان يكون آية ومعجزة للناس على قدرة ربنا الخالق\nزي ما خلق آدم من غير لا أب ولا أم، وخلق حواء من ضلعه، قاردر يخلق طفل من أم فقط بدون أب\n\"قَالَ كَذَلِكِ قَالَ رَبُّكِ هُوَ عَلَيَّ هَيِّنٌ وَلِنَجْعَلَهُ آيَةً لِلنَّاسِ وَرَحْمَةً مِّنَّا وَكَانَ أَمْرًا مَّقْضِيًّا\"\n☆في هنا فايدة لنا...وهي إن مريم مقالتش للرجل إللي هو جبريل عليه السلام إنت كذاب ..هو في امرأة تحمل بدون رجل..وابعد عني و..و..\nلأن العاقل لا يُكذّب إللي بيقول له كلام لحد ما يكمل معاه ويستفهم ويشوف الدليل على الكلام وهل هو صادق ولّا لأ..\nمش مجرد ما أقولك ده حصل كذا وكذا تقوليلي كذابة \nفلازم نفهم الأول ومنحكمش على حاجة بصدق ولا كذب إلا لما نتأكد ونفهم \n◇نرجع لتدبر القرآن\nلما قالت 《لم يمسسني بشر》 ليه مقالتش لم يمسسني أحد\nالمس هنا المقصود به هو الجماع فلو إنها قالت لم يمسسني أحد يبقى كده الجان هيدخلوا في الآية، ومفيش زواج ولا علاقة زوجية بين البشر والجان يكون نتيجته حمل\nفهي قالت بكل دقة إن لم يمسها أي بشر \n¤معلومة عالسريع\nيَحرم الزواج بين الجن والإنس على افتراض إن ده ممكن يعني\nلأن ربنا قال لنا : \"وَاللَّهُ جَعَلَ لَكُم مِّنْ أَنفُسِكُمْ\"\nوقال: \" وَمِنْ آيَاتِهِ أَنْ خَلَقَ لَكُم مِّنْ أَنفُسِكُمْ أَزْوَاجًا\"\nثم متخيلين كل واحدة ممكن تحمل حمل حرام تيجي تقول ده أنا حملت من الجني فلان\nبعد ما أخبر جبريل عليه السلام مريم إن حملها أمر من ربنا مفهوش رجعة، نفخ فيها الروح وحملت مريم بعيسى عليه السلام\n◇يعني إيه بقى الكلام ده \nالنفخ معناه إني أطلع هواء من فمي .. النفخ المعروف يعني لما تنفخ في أي حاجة ..ده أصل النفخ،\nفربنا أمر جبريل عليه السلام إنه ينفخ في جيب الدرع إللي كانت مريم بتلبسه، وهو رقبة الثوب ومدخل الرأس،\nعارفين لما نيجي نلبس جلابية أو عباية؟  ..بندخل راسنا منين \nأهي هي الفتحة دي.. حاجة زي كده \nفجبريل عليه السلام نفخ في المكان ده والنفخة دخلت في رحم مريم عليها السلام بأمر ربنا،\nوعيسى عليه السلام هو الوحيد إللي جبريل عليه السلام نفخ فيه الروح، أما باقي البشر ففي ملك معين مسؤول عن نفخ الروح فيهم بعد تكوينهم في الرحم،\nفنفخ الروح كان بداية خلق عيسى عليه السلام في رحم أمه مريم وبعدين كمل مراحل نمو الجنين العادية\n \nحملت مريم عليها السلام بعيسى على أرجح الأقوال تسعة أشهر زي باقي النساء، ويقال إنهم ثمانية أشهر..\n¤سؤال ..ربنا قال إن عيسى روح الله \n\" فَنَفَخْنَا فِيهِ مِن رُّوحِنَا \" \nهل ده معناه إن عيسى جزء من ربنا\nطبعا لأ...الإضافة هنا إضافة تشريف وتكريم..فاكرين في قصة صالح عليه السلام لما ربنا خلق الناقة وصالح عليه السلام قال لقومه: هذه ناقة الله..وكمان الكعبة بنسميها بيت الله..كل الحاجات دي منسوبة إلى الله تعظيما وتشريف مش أكثر\nيعني مش زي ما نقول علم الله وقدرة الله وسمع الله وبصره..دي صفات متصلة بربنا..بعكس الروح إللي بنضيفها لله عشان نبين مكانتها زي ما قلنا\nحملت مريم بعيسى عليه السلام وسلمت أمرها لله\nأنا عايزاكم تتخيلوا مشاعر مريم عليها السلام\nشوفوا لو وصل لنا إن حد بيتكلم علينا مجرد كلام عادي وبيجيب في سيرتنا بنكون متضايقين إزاي\nدي واحدة حامل من غير زوج وهي أصلا منقطعة للعبادة يعني مكنتشي ناوية زواج من أصله،\nوهي مش شخصية عادية إطلاقا \nدي واحدة مشهورة بين الناس يعني العين عليها والناس مركزة معاها بزيادة،\nوكمان أبوها كان كبير العلماء عندهم، هيقولوا عليها كانت بتمثل الطهر والعفاف وكذا وكذا،\nتخيلوا إن كل ده بيدور في رأس بنت صغيرة لسه يادوب خمسة عشرة سنة\nبطنها بدأت تكبر والناس بقت تبص لها نظرات ريبة\nفانعزلت عن الناس خالص عشان محدش يعايرها بالحمل بدون زوج، وراحت في وادي بيت لحم،\nوفضلت هناك لحد ما جاء وقت ولادة عيسى عليه السلام\nقبل ولادة عيسى بثلاثة شهور ويقال ستة أشهر اتولد مييين\nده إللي هنعرفه الجزء الجاي إن شاء الله \n#قصص_الأنبياء\n#الحلقة_الرابعة_والخمسون\n#مريم_زكريا_الجزء_الرابع\n#يحيى\nاتكلمنا عن زكريا عليه السلام لما دعا ربنا إنه يرزقه بولد عشان يرث النبوة، وربنا استجاب دعاؤه وحملت زوجته \"إشياع\" بيحيى عليه السلام، \nولدت إشياع يحيى عليه السلام، وكان يحيى مختلف عن باقي الأطفال؛ لإن ربنا أعطاله الحكمة والفَهم من وهو صغير ،\nحتى لما كِبِر شوية وكان الأطفال يقولوا له تعالى نلعب كان بيقول لهم:\nاحنا متخلقناش للعب وكان يسيب اللعب ويتعبد لله، و ده إللي ربنا قال عنه في القرآن: \n\" وَآتَيْنَاهُ الْحُكْمَ صَبِيًّا\"\n◇وممكن نشوف الكلام ده مع أطفال صغيرين حوالينا تلاقي البنت على صغر سنها تطلب إنها تلبس الحجاب،\nوتلاقيها منها لنفسها كده متجهة لطاعة ربنا بالرغم إن إللي حواليها مش في دماغهم أصلا وكل همهم يلبسوا على الموضة ويتفسحوا ويتحرروا من أي أوامر أو التزامات شرعية و...و...\nفلما تلاقي بنتك ولّا أختك ولا أي طفلة أو طفل ماشيين في طريق ربنا شجعهم كتير،\nيمكن تشجيعك ليهم ده يكون سبب في ثباتهم على الدين وتكون أعمالهم بسبب تثبيتك لهم في ميزان حسناتك \nواوعوا.. \n \nإوعوا تقولوا للبنت مثلا \"يا حبيبتي انتِ لسه صغيرة\"،\nولا \"عاملة في نفسك كده ليه!\"، ولا أي كلام من الكلام المحبط ده إللي بيقتل الهِمم والعزائم ده \nلو البنت رجعت عن الإلتزام بطريق ربنا وكنتم انتم السبب ، هتبقى في ميزان سيئاتكم\nولازم تكونوا عارفين إن المسلم إللي بينشأ في طاعة الله، بيكون من السبعة إللي ربنا بيظلهم يوم القيامة من حر الشمس في ظل عرشه لما تكون الشمس قريبة جدا من رؤوسنا نسأل الله السلامة..\nمش لو حد فينا شاف طفل واقف في عز الشمس مش بيصعب علينا؟\nأهه يوم القيامة هيبقى أشد من حر الدنيا \nفياريت يصعب عليك هناك أكتر من الدنيا، وخلوا أطفال المسلمين يبنوا لأنفسهم ظلهم يوم القيامة بدون ما تحبطوهم\nالمهم،\nيحيى عليه السلام كان طائع لربنا من صغره وزاهد في اللعب ، وعنده جدية في الإلتزام، وده كان بسبب إن ربنا قال له《يَا يَحْيَى خُذِ الْكِتَابَ بِقُوَّةٍ》\nيعني خد التوراة باجتهاد وبجدية وهمة عالية.. ومش هتعرف تاخدها بجِد واجتهاد غير لما تفهمها صح الأول،\nولما تفهمها صح ساعتها العقيدة هتستقر عندك وتقدر تطبقها في أقوالك وأفعالك كلها \n☆وطبعا الكلام ده لما ربنا بيقوله في القرآن فهو مش ليحيى لوحده، ده لينا احنا كمان \nيعني ربنا بيقول لنا خدوا القرآن بجدية.. افهموه صح عشان تعرفوا تطبقوه.. \nفلما ربنا يقول أطيعوا الله وأطيعوا الرسول،\nيبقى لازم تاخد الموضوع بجدية وأول خطوة في الجدية دي أكيد هي:\nإنك تتعلم وتفهم إيه هي الأوامر دي إللي مفروض تطيعها، \nوبعدين تاني خطوة في الجدية بتكون إنك تطيع كل الأوامر دي،\nمش الموضوع يبقى على حسب ظروفك ومزاجك وهواك: ده هطيعه وده لأ؟ \n \"أَفَتُؤْمِنُونَ بِبَعْضِ الْكِتَابِ وَتَكْفُرُونَ بِبَعْضٍ \"؟!\nيعني ما ينفعش مثلا تقول :\nوالله أنا هطيع ربنا وأصلي وأقرأ قرآن وأصوم وأزكي، \nلكن الموسيقى مش هقدر، لازم أسمع\nأو السينما دي روحي، معرفش أعيش من غيرها،\nأو كله إلا الاختلاط مش هقدر مكلمش زمايلي ونخرج مع بعض\nالدين يا جماعة ماينفعش ناخد نصه ونسيب نصه، ولا حتى نسيب حتة منه بمزاجنا...\nآه ممكن نقصر غصب عنا ونكون زعلانين بسبب تقصيرنا في فريضة أو معصية،\nلكن ميبقاش بمزاجنا: الأمر الإلهي ده هعمله لإنه سهل، وده لأ مش هعمله لإني مش مقتنع إنه فرض أو هيضايقني لو عملته.. الدين مش كده.. \nالدين ناخده كده كله على بعضه \nثم لو كل حاجة سهلة كده يبقى فين أجر المجاهدة \nوكمان الجنة حُفّت بالمكاره يعني متحوّطة كده بالحاجات إللي بنكره نعملها...الحاجات إللي هي ضد هوانا\nيعني مش هندخل الجنة غير لما نكسر المكاره دي\nزي كده لما واحد بيعدّي حواجز عشان يوصل لهدفه\nوربنا بيقول لنا:\n\"أَمْ حَسِبْتُمْ أَن تَدْخُلُوا الْجَنَّةَ وَلَمَّا يَعْلَمِ اللَّهُ الَّذِينَ جَاهَدُوا مِنكُمْ وَيَعْلَمَ الصَّابِرِينَ\"\nفين بقى مجاهدتنا لنفسنا وصبرنا على الطاعة وصبرنا عن المعصية \nهو مين إللي بيبقى عايز يقوم في عز البرد يحط مية على جسمه عشان يتوضى؟\nوالله لولا إننا بنجاهد عشان نرضي ربنا وناخد الأجر مكنش في حد قام من تحت البطانية \nعلى فكرة الكلام ده لا يتعارض مع حديث لن يدخل أحد الجنة بعمله \nلأن واحد من الصحابة قال لرسول الله ﷺ خلاص بلاش نعمل ..فرسول الله قال:\n\"اعملوا فكل مُيَسر لما خُلق له\"\nفلما الواحد يلاقي نفسه واخدة الكتاب بقوة وماشية في طريق ربنا هنا نعرف إن ربنا ميسّرنا لطريق الجنة \nربنا قال لنا اعمل كذا..حاضر يارب حاااالا،\nمتعملش كذا..حاضر يارب حااالا..مش نستنى لما نشوف ظروفنا تسمح ولّا لأ..ولا نقعد ندور على شيخ يقولنا عادي لو معملتش كذا أو يجوز إنك تعمل كذا على حسب الهوى\nفيحيى عليه السلام من صغره وهو بيطيع أمر ربنا\nطب إيه باقي صفات يحيى عليه السلام؟\nمن الحاجات إللي ربنا رزقه بيها كانت: الحنان.. يعني الرحمة والعطف والشفقة والرأفة...\n\"وحَنَانًا مِّن لَّدُنَّا وَزَكَاةً وَكَانَ تَقِيًّا..\"\nولو ركزتم هتلاقوا إن الصفة دي لها حكمة رائعة \nلما اتولد يحيى عليه السلام، كان زكريا عليه السلام وزوجته إشياع عمرهم كم ؟\nكانوا قريبين من المائة سنة\nيعني كانوا محتاجين حد يكون حنين عليهم في سنهم الكبير ده، فربنا وهبه الحنان الوافر من فضله عز و جل بجانب البر،\nلأن الإنسان ممكن يكون بار بأبويه من غير ما يكون حنيّن\nيعني يحسن إليهم ويسمع كلامهم وكل حاجة لكن مفيش حنية تتحس من تصرفاته أو أفعاله\nده غير كده كمان مكنش بيرهقهم باللعب الكتير وهو صغير زي باقي الأطفال لإنه مكنش له في اللعب أصلا عليه السلام\nوفي خاصية كمان ليحيى عليه السلام ربنا اختصه بيها وحده عن كل بني آدم، \nوهي إنه مش بس معملش أي خطأ... لأ، ده حتى مفكرش ولا جه على باله كده إنه يعمل الغلط:\nربنا قال:\n \"سَيِّدًا وَحَصُورًا وَنَبِيًّا مِّنَ الصَّالِحِينَ\"، وكنا قلنا من حلقتين فاتوا إن \"سيد\"  يعني شخص كلمته مسموعة وليها أثر في الناس وبيتبعه ناس كتير، \nوقلنا إن \"حصور\" يعني معصوم من الذنوب، لا يأتيها، يعني كإنه حُصِرَ عنها فبقى مانع نفسه من الشهوات الضارة ومن إنها تأثر عليه..\nخلونا نقول مثال عشان المعنى يوضح،\nمش ساعات كده نفس الواحد تقوله ماتيجي نشوف فيلم كذا ولّا مسلسل كذا ولّا نعمل كذا\nوساعتها الواحد بقى يا إما يستجيب لنفسه الأمارة بالسوء دي يا إما إنه يقول لها:\nلأ حرام مش هعمل كده، ويشغل نفسه بحاجة مفيدة، ويجاهد نفسه عشان ما يضعفش ويعصي،\nأهه أنا كإنسان طبيعي جه على بالي إني أعمل معصية معينة\nلكن يحيى عليه السلام بقى مبيجيش على باله أصلا إنه يعصي الله\nوالدليل على كده قول رسول الله ﷺ : \n\"ما من أحدٍ من ولدِ آدم إلا وقد أخطأ، أو هَمّ بخطيئة ، ليس يحيى بن زكريا\"\n☆وفي معنى تاني للحصور وهو إللي بيمنع عن نفسه شهوة الميل للنساء من أساسه، عشان يبقى منقطع للعبادة لله فقط\n¤طيب لو المعنى ده هو المقصود، مش دي كده تبقى الرّهبَانِيّة إللي ربنا نهانا عنها \nشوفوا، ربنا بيقول: \n\"وَاذْكُرِ اسْمَ رَبِّكَ وَتَبَتَّلْ إِلَيْهِ تَبْتِيلًا\"\nفي نوعين من التّبَتل.. \n◇نوع معناه إن الإنسان يفرَّغ نفسه لعبادة الله بعد ما يُلبي احتياجاته البشرية الطبيعية، زي الأكل والشرب والنوم وهكذا، وده تبتل محمود.. \nو التبتل ده إللي كانت عليه مريم \"البتول\" عليها السلام، \nيعني هي كانت منقطعة لعبادة لله وكمان زاهدة في الرجال، زي يحيى عليه السلام لما كان عابد لله و زاهد في النساء.. فكان التبتل إللي من النوع ده جائز في شريعة يحيى ومريم عليهما السلام\n◇النوع الثاني إللي هو الرّهبَانِيّة، والرهبانية دي كانت في النصارى مش في اليهود، \nيعني ربنا لما قال: \"وَرَهْبَانِيَّةً ابْتَدَعُوهَا ما كتبناها عليهم إلا ابتغاء رِضوانِ الله فما رَعَوْها حَقَّ رِعايَتِها\"\nكان بيتكلم عن النصارى إللي هم هييجوا بعد عيسى عليه السلام، \nوالرهبانية مذمومة لأنها بتشدد على النفس في العبادة فوق طاقتها بزيادة،\nزي الصيام كل يوم بدون راحة، وقيام الليل كله يوميا بدون راحة في الليل،\nده بالإضافة إلى إن الرهبانية كانت بتدعو لترك الزواج وبتدعو لترك أكل اللحم..\nفزي ما شوفنا، تبتل يحيى ومريم مش من النوع المذموم أو المنهي عنه..\nلأ كان بيتعبد لله، لكن بعد إعطاء الجسد حاجته الحياتية من راحة وأكل وغيره بدون حرمان ، ماعدا الزواج، فده بيكون زهدا فيه زي ما قلنا من شوية\nوكان من صفات يحيى عليه السلام كمان إنه كان بار بأبوه وأمه بيراعي ربنا فيهم جدا مش مجرد حنان فقط لأ، ده إحسان في الإرضاء والمعاملة،\nومكنش متكبر نهائي، بالعكس كان خافض للجَناح وطبعه ليّن ومتواضع، سواء مع أبويه أو مع الناس،\nومكنش بيظلم ولا بيقهر حد، كان بيُشِع صلاح في كل شيء، أعماله صالحة وعقيدته صالحة ونيته صالحة،\n\"وَبَرًّا بِوَالِدَيْهِ وَلَمْ يَكُن جَبَّارًا عَصِيًّا\"\nده غير إنه كان نبي وكمان ربنا ألقى عليه السلام في المواضع التلاتة للحياة اللي الإنسان بيكون فيها أضعف ما يكون؛\n لأنه بينتقل من عالم لعالم تاني، ومواضع الضعف التلاتة دي هي: \n◇يوم الولادة؛ لإن الإنسان بيكون داخل عالم جديد عليه وهو الدنيا،\n◇ويوم الوفاة؛ لإنه بيكون ساب العالم إللي اتعود عليه وداخل في عالم تاني أصعب وهو عالم القبور،\n◇ويوم البعث، إللي هيقوم فيه للحساب، ولاشك ده أصعب المواضع\nفلما كانت الأحوال الثلاثة دي أشق ماتكون على الإنسان ربنا سلم على يحيي وأعطى له الأمان والسلامة زيادة فضل وإنعام منه عز وجل على يحيى عليه السلام\nوربنا الشكور دايما بيكون كده مع العبد الطائع الشكور، بيضاعف له الفضل والإحسان\n\"وَسَلامٌ عَلَيْهِ يَوْمَ وُلِدَ وَيَوْمَ يَمُوتُ وَيَوْمَ يُبْعَثُ حَيًّا\"\nيعني يحيى عليه السلام كان حصور.. تقي.. سيد.. مؤثر في الجماهير.. حنون.. بار.. متواضع.. خافض للجناح.. زاهد في اللعب.. متبتل.. عالم.. فاهم.. حكيم.. حسن الأخلاق..\n☆وعايزكم تركزوا في صفات يحيى عليه السلام إللي قلناها دي كووولها وتخلوها في دماغكم عشان هنشوف إللي هيحصل بعد شوية\nعاش يحيى عليه السلام في بني إسرائيل، وكان محبوب ومعروف ، سيد بقى وبيتبعه ناس كتير زي ما قلنا\nفي يوم من الأيام يحيى عليه السلام جمع بني إسرائيل في بيت المقدس عشان يقول لهم خمسة أوامر ربنا أمره إنه ينفذها وإنه يأمر بني إسرائيل همّ كمان إنهم ينفذوها\nرسول الله ﷺ بيقول:\n\"إنَّ اللَّهَ أمرَ يحيى بنَ زَكَريَّا بخمسِ كلماتٍ أن يعملَ بِها ، ويأمرَ بني إسرائيل أن يعمَلوا بِها\"\nالأوامر دي كالتالي :\n♡الأمر الأول:\nأمرهم إنهم يعبدوا الله ولا يشركوا به شيئا،\nلأن إللي بيشرك بعبادة ربنا عامل زي واحد عنده خادم مشغله في محل وقال له الفلوس إللي هتكسبها تجيبهالي آخر اليوم\nفراح الخادم ده واخد الفلوس إللي كسبها دي وبدل ما يعطيها للراجل صاحب المحل راح موزعها للناس اللي ماشية في الشارع\nفهل حد فيكم يرضى إنه يكون عنده خادم زي ده\nولله المثل الأعلى، احنا ربنا خلقنا ورزقنا بكل شيء، فطبيعي نعبده هو فقط، مع الفارق طبعا إن ربنا عز وجل غني عن عبادتنا،\n لكن العبادة دي لمصلحتنا احنا وسعادتنا سواء في الدنيا أو في الآخرة\nو العبادة معناها هي كل حاجة ممكن الإنسان يعملها من الأقوال أو الأفعال الظاهرة و الباطنة ويكون ربنا بيحب الأفعال دي وراضي عنها،\nوالأفعال الظاهرة زي الصلاة والذكر والصِّدق وحسن الخلق وطلب العلم وتقديم النُّسُك والقرابين، \nوالأفعال الباطنة زي الخشوع والإخلاص و التقوى\n♡ الأمر التاني:\nقال لهم ربنا بيأمركم بالصلاة ..\nولما تصلوا متقعدوش تتلفتوا يمين وشمال وتنشغلوا بحاجة تانية غير الصلاة؛\nلإن ربنا بيبقى ناظر لقلب العبد وهو بيصلي، فلازم العبد يحقق الخشوع في الصلاة، وكل ما كان الإنسان مهتم بموقفه بين يدي الله في الدنيا، ربنا هيهون عليه وقفته بين يديه يوم القيامة \n♡الأمر التالت:\nأمرهم بالصيام... \nوطبعا احنا عارفين فضل الصيام، وإن رائحة فم الصائم أطيب عند ربنا من ريحة المسك\nفالصائم ده عامل زي راجل معاه كيس فيه مِسك ماشي بيه وسط الناس، أكيد ريحته هتبقى جميلة، ده غير التقوى إللي الصيام بيربينا عليها..\n♡الأمر الرابع:\nأمرهم بالصدقة.. \nومعروف فضل الصدقة طبعا، وهي زيها زي واحد ناس أسرُوه وخلاص هيقتلوه،\nوبعدين قال لهم لو أنا اديتكم فلوس تسيبوني؟\nفوافقوا، فقعد يفدي نفسه بالفلوس لحد ما حرر نفسه من إيديهم.. \nوكذلك الإنسان لما بيتصدق ، بيبقى بيحوّش لنفسه صكوك وأموال يفدي بيها نفسه في الآخرة عشان يحرر نفسه ويحميها من عذاب الله\n♡الأمر الخامس:\nأمرهم بذكر الله ..\nو ده بقى الحصن الحصين للإنسان.. فإللي بيذكر الله عامل زي واحد في أعداء بيجروا وراه، \nوبعدين فجأة لقى حصن حصين قصاده، فراح داخل فيه وأنقذ نفسه من الأعداء، \nفالإنسان طول ماهو بيذكر ربنا فهو في حصن منيع ضد كل أعداؤه، ضد الشيطان والدنيا والهوى وصحبة السوء\n☆عشان كده ربنا شرع لنا في الإسلام أذكار في كل وقت يكاد يكون مفيش حالة في يومنا إلا ولها ذكر،\nزي أذكار الإستيقاظ من النوم وبعدين أذكار الوضوء وبعدين أذكار الصلاة وبعدين أذكار الصباح وأذكار المساء وأذكار النوم.. \nولو مفيش حالة معينة للذكر في وقت معين، فربنا جعل لنا أذكار عامة نقولها برده في غير أوقات أذكار الأحوال،\nزي الاستغفار والحوقلة والتسبيح والتحميد والتكبير والتهليل والصلاة على النبي ﷺ وغيرهم كتير.. كل ده وإنت بتقوله بتكون في حصن منيع\nده غير إن أسهل عبادة وأعظمها أجر هي الذكر\nواحد جه لرسول الله ﷺ قال له:\nيارسول الله شرائع الإسلام كثرت علي..قيام الليل والصدقة والسنن و...و...\nفقل لي على شيء أتمسك به ومسبهوش أبدا..رسول الله ﷺ قال له : \"لا يزال لسانك رطبا من ذكر الله\"\nيعني داااايما اُذكر ربنا بتسبيح او استغفار أو..أو..\nطيب إشمعنا يعني الذكر \nرسول الله ﷺ بيقول:\nأقول لكم بأحسن عمل ممكن تعملوه وأكثر عمل ربنا يرضاه  وأكثر حاجة ترفع درجتكم ،\nوأحسن من إنكم تتصدقوا بالذهب والفضة وأحسن حتى من الجهاد ...الصحابة قالوا:\nبلى يا رسول الله\nقال ذكر الله\n☆طبعا مش عايزة واحدة تيجي تقولي يعني أسيب الصلاة وأقعد أذكر ربنا \nالكلام هنا عن فضائل الأعمال مش عن الأصول\nالمهم،\nدي كانت الأوامر الخمسة إللي يحيى دعا ليها بني إسرائيل..\nوعاش عليه السلام بينهم يدعوهم لأخذ الأوامر بجدية ويتابعهم، \nلحد ما في يوم من الأيام الحاكم الروماني هيرودس إللي اتكلمنا عنه قبل كده وقلنا إنه دخل في اليهودية حب يتزوج واحدة من محارمه يُقال إنها بنت أخوه،\nوزواج المحارم كان محرم في شريعة يحيى عليه السلام،\nفلما يحيى أنكر على الحاكم الأمر ده،\nالحاكم مقدرش إنه يخالف أمره، لإن يحيى كان خطيب الناس ومحبوب منهم وهو القائم بالنبوة بعد زكريا عليه السلام.. \nلكن البنت كانت طمعانة في المُلك ، فمش عاوزة تفوّت فرصة الزواج بالحاكم هيرودس، \nوكانت البنت دي بَغِي، يعني فتاة زانية بتبيع عِرضَها مقابل المال،\nوفي نفس الوقت والدتها كانت مشجعاها على إنها تتزوج من الملك،\nفتزينت البنت ودخلت على الملك عشان تُغويه ، فلما سمع كلام الشيطان ووافقها على الزنا، رفضت وقالت له: \nمش مسموح إلا بشرط.. إنك تتزوجني.. هي مش بتقول كده عشان هي عفيفة ، هي بتقول كده عشان بزواجها منه فقط هتكون ملكة..\nفالملك قال لها: بس يحيى قال لأ!..\nفقالت له: اقتله..! \nمهر زواجي هو إنك تجيبلي رأس يحيى \nففعلا بسبب غواية الشيطان له وغواية البنت البَغِيّ دي، الملك أرسل جنوده لمكان يحيى عليه السلام،\nوقطعوا رأسه وحطوها في طبق ورجعوا بالطبق للملك، وقدمه للمرأة البغي\nفربنا خسف بيها الأرض..!\nالبنت بدأت تغوص في الأرض وتصرخ، وأمها جنبها بتصرخ ..\nوأول ما قربت تغوص بالكامل في الأرض، أمها قطعت راسها عشان تقتلها وتخفف عنها الألم والرعب.. \nفالأرض لفظت جسد البنت بعد قطع رأسها،\nفبقت جثة راسها مقطوعة جنبها على الأرض، زي ما عملت في يحيى عليه السلام، والجزاء من جنس العمل، وما ربك بظلام للعبيد..\n◇قصة موت يحيى عليه السلام ذكرها ابن كثير في التفسير...\nلكن العلماء مختلفين برده هل يحيى قُتل أصلا ولّا مات بشكل طبيعي\nلإن مفيش نص صريح واضح بيقول إيه إللي حصل مع يحيى عليه السلام ومع زكريا.. كلها مجرد روايات لبعض المفسرين..\nويقال إن زكريا عليه السلام كان في دمشق لما قُتل يحيى عليه السلام،\nوإن بني إسرائيل نفسهم كانوا عايزين يتخلصوا من زكريا عليه السلام ويقتلوه فهرب منهم،\nوهروبه ده مكنش عشان نفسه لكن كان خايف عليهم ومش عاوزهم يتحملوا وزر قتل نبيين، هو وابنه يحيى،\nفلما وصل لمكان معين، دخل في شجرة انفتحت له زي الباب كده بأمر الله، \nفالشيطان مسك طرف ثوبه وخلّاه ظاهر للناس، وتجسّد الشيطان في صورة بشر، وقال لبني إسرائيل إللي كانوا بيبحثوا عن زكريا...إنتم بتدوروا على إيه؟ فقالوا له زكريا.. \nفقال لهم أهه، مش ده طرف هدومه؟ \nفقعدوا يخبطوا عالشجرة ويقولوا اخرج يا زكريا، فالشيطان قال لهم انشروا الشجرة بالمنشار،\nفجابوا المنشار ونشروا الشجرة وزكريا عليه السلام جواها  فقتلوه عليه السلام\n\"أَفَكُلَّمَا جَاءَكُمْ رَسُولٌ بِمَا لَا تَهْوَىٰ أَنفُسُكُمُ اسْتَكْبَرْتُمْ فَفَرِيقًا كَذَّبْتُمْ وَفَرِيقًا تَقْتُلُونَ\"\n☆يعني همّ مكنش عندهم ذرة عقل وتدبر كده \nمفكروش خالص هو إزاي ممكن حد يدخل وسط شجرة إلا لو كان دي بمعجزة من قوة إلهية غير بشرية\nيعني مكنش عندهم ذرة خوف من ربنا؟!\nبالبساطة دي بيتحدّوا ربنا عز وجل؟! \nيعني مش يقولوا إيه ده ! الشجرة انشقت وبعدين رجعت اتقفلت تاني وكان عايش جواها كمان ما اتفعصش يا جماعة إزاي ده حصل ! آمنا بالله \nلأ.. قتلوه بدم بارد وقلب كالحجارة أو أشد قسوة..\nوده حال بني إسرائيل على مر الزمن\n☆ملحوظة:\nاحنا كنا حكينا قبل كده عن قصة النبي أشْعِيا وإنه مات بنفس الطريقة دي كده،\nوالمفسرين مختلفين هل قصة القتل دي خاصة فقط بزكريا ولّا بأشعيا ولّا حصلت للاتنين بالفعل\nو القصتين دول من الإسرائيليات إللي رسول الله ﷺ قال نحكيها دون تصديق أو تكذيب\nفاحنا بنحكيها عشان نفهم الأحداث ماشية إزاي،\nلكن بصفة عامة ده كان حال بني إسرائيل دائما مع أنبياء الله مع اختلاف التفاصيل هنا أو هناك..\nوعشان كده ربنا استبدل أمتهم بأمة تانية غيرهم، إللي هي أمة محمد ﷺ، فلازم نستفيد من قصصهم ونتعلم\n◇من الفوائد كمان إللي ممكن نستفيدها من قصة يحيى عليه السلام، إنه بالرغم من كل صفاته دي ومكانته بين الناس، إلا إنه قُتل في النهاية على  يد بَغِي\nوده يصبرنا في كل زمان لما نلاقي الظالم والكافر والفاجر متسلطين على الصالحين المؤمنين.. يقتلوهم ..يعذبوهم.. يأخدوا أموالهم يظلموهم.. \nهل ده معناه إن الفجار دول أغلى عند ربنا من الأتقياء؟\nمستحيل طبعا،\nلكن من ضمن حكمة ربنا في ده إن الظالم يُضاعَف عليه العذاب في الآخرة، والمؤمن المظلوم يزداد في الدرجات والأجر،\nوصبر الله على الظالم مَكرُمة للمظلوم إذا صبر المظلوم ورضي بقضاء الله وثبت على الإيمان\nطب ليه\nلأن عداد الحسنات بتاع المظلوم شغال \nودي حسنات متعبش فيها\nالواحد لما بيكون عايز يعمل عمل صالح لازم يكون مخلص في العمل ده عشان ربنا يعطي له أجر العمل،\nفيقعد يجاهد نفسه عشان يبقى مخلص وياخذ أجر..لكن المظلوم مش محتاج مجاهدة في الإخلاص ده حسناته بتتكتب له وهو نايم\nأما زكريا عليه السلام، \nفربنا أراد له إنه يكسب أجر الصبر الجميل على فَقْد الابن، ومش أي فَقْد ده فَقَده بعد عطش السنين، فياخد أجر الصبر العظيم ويكون قدوة للناس في ده على مر الزمن\nوكمان همّ كده كده هيموتوا\n \nسواء زكريا أو يحيى أو غيرهم من أهل الحق في كل زمان.. فيموتوا شهداء في سبيل الله أكيد أفضل خاتمة الواحد ممكن يختارها لنفسه\nو كما قيل: هي متيةٌ واحدة، فلتك في سبيل الله\nبعد موت يحيى وزكريا عليهما السلام، مين النبي إللي ربنا أرسله في بني إسرائيل\nإيه ده\nهو لسه فيهم أمل بعد كل إللي عملوه ده\nده إللي هنعرفه إن شاء الله في ا"}, {"n": 38, "l": "الحلقه ٥٥ | عيسي ١ | والحلقه ٥٦ | عيسي ٢", "u": "https://www.facebook.com/groups/710210019782034/permalink/760513558085013/", "t": "#قصص_الأنبياء\n#الحلقة_الخامسة_والخمسون\n#مريم_زكريا_الجزء_الخامس\n#عيسى_الجزء_الأول\nاتكلمنا عن مريم عليها السلام وإنها كانت منقطعة للعبادة عشان كده اسمها مريم البتول، \nوعلى فكرة كلمة \"القِدّيسة مريم\" دي من وصف النصارى لمريم رضي الله عنها، \nوالكلمة دي من الغُلُو في وصف مريم،\nفاحنا كمسلمين منقولش الكلمة دي.. ربنا وصفها بالصِّدِّيقة ، وليها أوصاف تانية في الإسلام ، لكن وصف《 قِدّيسة》 ده مش تبعنا خالص، يعني كإن في إيحاء كده إنها مقدسة، والقُدسِية لله وحده عز وجل\nوقلنا إنها حملت بعيسى عليه السلام بدون أب وإنها انعزلت بحملها عن الناس،\nوقلنا إن حمل عيسى عليه السلام كان تسعة أشهر على أرجح أقوال العلماء،\nبعد ما خلصت مدة الحمل وجاء وقت الولادة ،\nألم الولادة اضطر مريم عليها السلام إنها تلجأ لجذع نخلة تسند عليه وتولد عنده بعيد عن عيون الناس،\n\"فَأَجَاءَهَا الْمَخَاضُ إِلَى جِذْعِ النَّخْلَةِ\"\n☆ عايزاكم تتخيلوا معايا شابة صغيرة عفيفة في موقف زي ده، بتولد لوحدها من غير ما يكون أي حد معاها لا أم ولا أب ولا أخ...ومش بس كده الطفل إللي بتولده ملهوش أب\nالواحدة لما بتكون بتولد بتبقى تعبانة وخايفة وقلقانة و...و...\nمع إن أهلها حواليها وزوجها معاها ومطمنة إن بعد الولادة كل الأمور متجهزة للمولود الجديد،\nمريم عليها السلام اجتمع عليها تعب الولادة والألم النفسي بتاع الوحدة ومفيش حد يراعيها ولا يعطيها أكل ولا ماء،\nوكمان الخوف من مواجهة الناس بالمولود ده\nفكل المشاعر دي متجمعة جواها فتعبتها نفسيا جدا وخلتها تتمنى الموت، \nوقالت ياريتني كنت مت قبل ما يحصل لي كده ، وكانت الناس نسيتني ونسيِت كل حاجة عني\n\"قَالَتْ يَا لَيْتَنِي مِتُّ قَبْلَ هَذَا وَكُنتُ نَسْيًا مَّنسِيًّ\" \n◇إيه ده ثواني كده\n هو مش تمنّي الموت منهِي عنه؟ وكده يبقى جَزع وعدم رضا بقضاء الله\nأيوة، بس في وضع مريم هنا الأمر مختلف.. لإن مريم لما تمنت الموت كان لسببين \n◇الأول:\nإنها خافت إن الناس يظنوا بها الشر في عفّتها وتقواها ، فيعايروها بتهمة تمس الشرف فده يخليها تُفتن في دينها ،\nويجوز للإنسان إنه يتمنى الموت لو خاف على نفسه فتنة في دينه، \nحتى رسول الله ﷺ قال إن في حاجتين الإنسان بيكرههما :\nالموت، والموت أفضل للمؤمن من 《الفتنة》 والحاجة التانية قلة المال، وقلة المال أقل في الحساب ،\nلكن مينفعش الإنسان يتمنى الموت لو أصابه ضرر أو أذى أو ابتلاء بشكل عام زي مرض مثلا أو فقر أو غيره\n◇الثاني:\nإنها خافت على قومها إنهم يقعوا في البهتان وقذف محصنة عفيفة، ويكون ده بسببها...يعني تكون سبب إن قومها يقعوا في معاصي،\nزي مثلا لما تكرهي إن تحصل مشكلة أو فتنة بين الناس بسببك.. أكيد محدش بيتمنى لحظة زي دي\nفمريم مكنتش عايزة قومها يقعوا في الغلط بسببها، فتمنت الموت.\n☆وفي هنا فايدة لنا وهي إننا لا نتمنى الموت عشان حصل لنا ابتلاء ...مش يمكن البلاء ده يكون هو سبب تغير حياتنا\nهي مريم اتمنت الموت بسبب ابتلاء وفي ظنها إن ده أسوأ وضع ممكن تتعرض له واحدة في حياتها، لكن كان نتيجته إيه؟\nبقت أم لرسول من أولي العزم ، وكمان هيُنسب ليها هي، وهتفضل سمعتها مُبرأة زي ما هي،\nلأ وكمان هتبقى أيقونة في العفة لكل العالمين، بعد ما كانت من الأخفياء في زمن بني إسرائيل فقط\nفبلاش نتمنى الموت بسبب أي بلاء يحصل لنا أيا كان نوعه، لكن نصبر الصبر الجميل بيقين ميتهزش، يقين في إن رب الخَير لا يأتي إلا بالخَير \nلما مريم عليها السلام تمنت الموت كان التمني ده لمجرد لحظات، فهي لما قالت يا ريتني كنت مت، ناداها جبريل عليه السلام من أسفل الوادي يطمئنها،\nوكان المكان ده في بيت لحم وكانت ولادة عيسى عليه السلام على أرجح الأقوال في الصيف، \nواستدل العلماء إن الولادة كانت في الصيف بالكلام الموجود في الروايات التاريخية بأن الرعاة كانوا بيمشوا في الليل بأغنامهم في زمن ولادة عيسى، \nوفي الشتاء، البرد بيكون شديد وأحيانا بيكون في ثلج في بلاد الشام وبالتالي مفيش أحد بيتحرك في الليل\nيعني احتفال النصارى بمولد عيسى عليه السلام سواء في شهر ديسمبر أو شهر يناير ملوش أصل تاريخي صحيح \nفناداها جبريل وقال لها متزعليش ربنا جعل تحتك نهر صغير تشربي منه،\n\"فَنَادَاهَا مِن تَحْتِهَا أَلاَّ تَحْزَنِي قَدْ جَعَلَ رَبُّكِ تَحْتَكِ سَرِيًّا\"\n◇ويُقال إن إللي ناداها كان عيسى ولكن الراجح هو جبريل،\nفجبريل ناداها وطمنها، وقال لها ماتزعليش ومتخافيش، بصي ِلِمعِية ربنا إللي بتحاوطك واطمني،\nربنا جعل تحت منك نهر صغير تشربي منه، وهزي النخلة إللي وراكي بإيدك كده بس هتنزل عليكِ رُطَب .. \n\"وَهُزِّي إِلَيْكِ بِجِذْعِ النَّخْلَةِ تُسَاقِطْ عَلَيْكِ رُطَبًا جَنِيًّا\"\nفكلي واشربي وكوني مطمئنة البال وأبشري، ربنا معاكِ ومش هيضيعك وهيدفع عنك الأذى.. \n\"فَكُلِي وَاشْرَبِي وَقَرِّي عَيْنًا\"\nرحمة عظيمة من ربنا لمريم في توقيت مهم جدا بالنسبة لها،\nيعني هي إزاي هتقدر تاكل وتشرب في الموقف ده وخصوصا إن الإنسان ميقدرش ياكل وهو خايف، حتى ربنا بيقول :\n\" وَلَنَبْلُوَنَّكُمْ بِشَيْءٍ مِنَ الْخَوْفِ وَالْجُوعِ \"\nفهو قدم الخوف هنا على الجوع لأن الخوف ممكن ينسي الإنسان الجوع،\nفربنا بيطمّن مريم رضي الله عنها وبيقول لها تاكل وتريح أعصابها وتهدّي نفسها خالص، وهو كده بيُهيأها للمواجهة إللي هتحصل بعدين\nفأعظم سلاح الإنسان ممكن يتسلح به هو سلاح الإطمئنان \nعارفين، زي مثلا لما الواحد يكون عنده امتحان ومذاكر  كويس ،\nوبعدين لما يوصل للإمتحان يسمع كلام من إللي حواليه إن الإمتحان هييجي صعب والمادة دي امتحانتها صعبة،\nأو الدكتور ده بيسقط ناس كتير،\nفهيحس بالخوف لدرجة إنه ممكن ميعرفش يحل وينسى إللي كان مذاكره،\nلكن تخيلوا كده مثلا إن سكرتير القسم طلع وقعد يطمّن الطلبة ويقول لهم الكلام ده مش صحيح، \nوالامتحان في مستوى الطالب المتوسط أصلا، كله هينجح إن شاء الله متقلقوش.. هيحس بإيه ساعتها؟\nهيحس براحة وأمان طبعا، وهيدخل يواجه الامتحان\nويحل بكل سهولة \nأهه الإطمئنان ده هو سر النجاح في مواجهة أي شيء،\nعشان كده ربنا قال لمريم عليها السلام: قَرِّي عَينًا،\nمش بس متخافيش، لأ اطمني خالص وكوني مرتاحة البال وافرحي كمان بمولودك وميكونش في بالك أي قلق نهائي\nفمع الكرامات إللي شافتها ..النهر الصغير ..والرطب إللي نزلت من النخلة إللي مكنتش فيها ثمر ولا ورق أصلا؛\n اطمنت وقلبها هدِي خالص بعد كل ده\nفكل ده ربنا بيجهزها نفسيا عشان تقدر تواجه أي إنسان،\nوربنا قال لها على لسان جبريل عليه السلام إن أي بشر تشوفيه قولي له إنك صايمة ومش هتكلمي أي إنسان\n\"فَإِمَّا تَرَيِنَّ مِنَ الْبَشَرِ أَحَدًا فَقُولِي إِنِّي نَذَرْتُ لِلرَّحْمَنِ صَوْمًا فَلَنْ أُكَلِّمَ الْيَوْمَ إِنسِيًّا\"\nيعني ربنا بيقول لها إن أول بشر تقابليه تقولي له إنك صايمة و حتى مش هتكلمي أي إنسِيّ،\nومقلش أي 《بشر》 \nلأن الإنس جاية من الأُنس، فمعنى الكلام إن حتى لو جالي حد يُؤنسني ويخفف عني مش هكلمه\n◇طب وهي إزاي هتقول الكلام ده وهي صايمة عن الكلام\nفاكرين زكريا عليه السلام لما دعا ربنا وقال يارب اجعل لي آية ، فربنا سَلب منه خاصية الكلام، \nيعني مكنش قادر يتكلم مع أي حد خالص من أول ما خرج من المحراب، حتى لو كان عايز،\nبعكس مريم عليها السلام فهي إللي هتسكت بإرادتها\n☆إممم طب سؤال بس، هو ليه ربنا قال لمريم تهز جزع النخلة \nمش هو كان بيرزقها فاكهة الصيف في الشتاء وفاكهة الشتاء في الصيف وهي مش تعبانة،\nمش الأَوْلى دلوقتي إنه يرزقها بدون ما تبذل أي مجهود لأنها في أشد ضعفها وكمان لوحدها \nشوفوا،\nهو كأن ربنا بيقول لها وبيقول لنا إن مش معنى إن الرزق ممكن يجيلك في يوم من الأيام وإنت قاعد من غير ما تأخذ بالأسباب يبقى تعتمد على كده وتسيب الأخذ بالأسباب\nربنا أعطى لمريم كرامة في وقت معين لكن في الموقف ده \nفكإنه عز وجل بيقول لنا: \nمهما كانت حالتكم صعبة، لازم تاخدوا بالأسباب إللي تقدروا عليها، حتى ولو كان سعي بسيط جدا زي هزة النخلة بإيد، و زي ضرب موسى للبحر بالعصا.\nو زي كده لما ربنا يفتح لنا باب خير من أبواب الإلتزام...يعني بعتلنا حد ينصحنا، بعتلنا آية نسمعها فالقلب رَق، و...و...\nأهه كل ده رزق ربنا بعتهولك بدون سبب\nمينفعش بقى نعتمد على كده وننام في الخط وأقول لما ربنا يبعتلي تاني ولّا لما ربنا يأذن ولّا...ولّا....\nلازم هنا ناخد بالأسباب برده..نسمع قرآن زيادة، نصلي أكثر، نسمع دروس وعظ أكثر..\nفالخلاصة إنك حتى لما ربنا يرزقنا بدون سبب؛ ده مش مبرر إننا نعطل الأخذ بالأسباب،\nحتى من أدب الدعاء إننا نأخذ بالأسباب،\nمينفعش نقعد نقول يارب نجحني وأنا طول السنة مبذاكرش نهائي\nمينفعش أقول يارب اهديني وأنا مش واخدة بأسباب الهداية..يعني واحد يقول يارب اهديني إني أبطل اسمع أغاني وهو عمال يسمع ويغني وينزل أغاني جديدة على تليفونه وينشر هنا وهناك\nفين الأخذ بالأسباب...فين إنك تمسح الأغاني، فين إنك تلغي كل متابعاتك للصفحات إللي بتنزل أغاني..فين..فين..\nمفيش حاجة بتيجي للإنسان على طبق من ذهب\nلازم ناخد بالأسباب مهما كانت بسيطة...\nيعني هي مريم عليها السلام فيها نفس أصلا عشان تهز جزع نخلة\nده احنا لو طلبنا من رجل إنه يهز جزع نخلة مش هيقدر،\nفما بالنا بامرأة وكمان في أضعف حالاتها،\nفهي رسالة من ربنا لنا كلنا: عايز حاجة؛ اعمل السبب بتاعها مهما شوفت إن السبب ده بسيط لا يُذكر\n¤استنوا بقى عشان محدش يفهم غلط\nفي ناس تقعد تدعي يارب اهديني وهي مكبرة دماغها ومش بتدور على أي سبب من أسباب الهداية،\nوانتم اكيد عارفينهم وقابلتوهم\nوفي ناس بتدعي بالهداية ونفسهم فعلا من قلبهم إن ربنا يهديهم حتى لو كان باين عليهم عكس كده،\nفالناس دي ربنا بيهديهم فعلا لأنهم بيكونوا صادقين،\nفمش هم دول إللي أقصدهم خالص بكلامي إللي قلته من شوية\nبعد ما مريم عليها السلام اطمنت وأكلت، وزي ما بنقول شمّت نفسها\nراحت تقابل قومها بني إسرائيل وفي إيديها عيسى عليه السلام في اللّفة\nالطبيعي إني لما أشوف إنسان صالح وأنا عارفة صلاحه كويس، عمل حاجة غلط المفروض إني أسأله وأستفهم منه وأحسن الظن به...\nطبعا ده لو أنا إنسانة كويسة ومش مبصدق ألاقي غلطة عالناس الصالحة عشان أقدح فيهم وأتهمهم وأذلهم بيها وأعايرهم و أشْمت فيهم\nبني إسرائيل عملوا إيه بقى \nمريم عليها السلام دخلت عليهم بطفل في إيدها ..وأنا عايزاكم تتخيلوا موقفها كان عامل إزاي ولّا همسات و نظرات الناس لها وهي ماشية وفي إيدها طفل\n\"فَأَتَتْ بِهِ قَوْمَهَا تَحْمِلُهُ \"\nقالوا لها :\nيا مريم إيه اللي انتِ عملتيه ده! تقعي في الزنا يا مريم\n\"قَالُوا يَا مَرْيَمُ لَقَدْ جِئْتِ شَيْئًا فَرِيًّا\"\nيا أخت هارون- يعني من شدة عبادتها بيشبهوها بعبادة هارون عليه السلام- \nيا شبيهة هارون في العفة والحياء؛ أبوكِ عمره ما كان رجل سيء السمعة أو فاسق، ولا أمك كانت بغي من البغايا.. فإزاي إنتِ تعملي عملة زي دي\n\"يَا أُخْتَ هَارُونَ مَا كَانَ أَبُوكِ امْرَأَ سَوْءٍ وَمَا كَانَتْ أُمُّكِ بَغِيًّا\"\n☆ناس كذبوا الأنبياء وقتلوهم متوقعين منهم إيه\nمش مثلا يصبروا ويستفهموا منها الأول؟!\nمبيسألوش... هم قرروا خلاص مع نفسهم\nوهم أصلا عارفين عفتها وطهارتها وعارفين هي بنت مين واتربت إزاي وحتى قالوا لها يا أخت هارون زي ما شوفنا،\nومع ذلك أول حاجة قالوها إنهم اتهموها في عرضها\nعارفين زي إيه\nلما تكون امرأة ملتزمة بطريق ربنا ولّا لابسة نقاب وحصل منها خطأ غير مقصود أو عملت حاجة وبان منها للناس إنها عملت خطأ بيقولوا لها إيه؟\nأيوة يا أم نقااب..أيوة ياست الشيخة...هو ده الدين بقى\nكلام ظاهره حق أهه لكن وراه شماتة ربنا يعافينا\nطبعا مريم عليها السلام في موقف لا تُحسد عليه \nوهي نفذت أمر ربنا بالصيام ومبتتكلمش ولا بترد.. ومش عارفة تعمل إيه ، غير الطاعة.. والصبر.. \nفربنا ألهمها إنها تشاور على ابنها الصغير إللي بين إيديها في اللفة\nيعني كأنها بتقولهم متسألونيش أنا اسألوه هو\n\"فَأَشَارَتْ إِلَيْهِ\"\nفبدأوا يسخروا منها ..إيه ده...إزاي نكلم طفل رضيع \n\" قَالُوا كَيْفَ نُكَلِّمُ مَن كَانَ فِي الْمَهْدِ صَبِيًّا\"\n☆ملحوظة: \n همّ مكنوش يعرفوا إن الطفل إللي مع مريم ده ولد ، صبي مذكر يعني،\nهمّ قالوا صبي بشكل عام قصدهم طفل وخلاص، \nلكن مكنوش يعرفوا هل هو ذكر ولّا أنثى\nزي لما نقول مثلا على المرأة الحامل: حامل في عيل، بنتكلم بشكل عام، دون تحديد ذكر أو أنثى.\nفلما مريم رضي الله عنها أشارت لابنها إيه إللي حصل\nده إللي هنعرفه الجزء الجاي إن شاء الله\n#قصص_الأنبياء\n#الحلقة_السادسة_والخمسون\n#مريم_زكريا_الجزء_السادس\n#عيسى_الجزء_الثاني\nاتكلمنا المرة إللي فاتت عن مريم عليها السلام لما وضعت عيسى عليه السلام وراحت بيه لقومها وشوفنا إزاي اتهموها في عرضها،\nوهي كانت صايمة عن الكلام وأشارت لعيسى عليه السلام وهي ماتعرفش إيه إللي هيحصل،\nوالكل مستني ومستغرب، وفجأة لقوا صوت طالع من بين إيديها وبيكلمهم، عيسى بن مريم عليه السلام نطق \nأنطقه الله وهو لسه رضيع مكملش كام يوم في اللفة \nربنا أنطق الطفل الرضيع في المهد عشان يدافع عن أمه،\nهي تعرفت لله في الرخاء وكان عابدة وكان عندها رصيد،\nفلما جاء الاختبار والابتلاء ربنا أكرمها بمعجزة\nوشوفوا بقى أول حاجة قالها الطفل الرضيع كانت إيه:\n\"قَالَ إِنِّي عَبْدُ اللَّهِ \"\nيعني أنا مش إله ولا ابن إله ولا أي حاجة من دي خالص، أنا مجرد عبد لله،\n\"إِنِّي عَبْدُ اللَّه..ِ آتَانِيَ الْكِتَابَ.. وَجَعَلَنِي نَبِيًّا\"\nأعطاني الله الإنجيل، يعني ربنا آتاه الإنجيل والنبوة من زمان أوي من وقت ما قضى القضاء قبل أن يُخلق الخلق مش إن الإنجيل والنبوة معاه حالا،\nلأ ده هيكون في المستقبل لما يكبر بس هو بيحكي عن حاجة هتحصل\n  \nفأعطاني الإنجيل، وجعلني نبي ليكم ، يعني محدش يطعن فيّ ويقول إني ابن زنا وانتم عارفين إن مستحيل الأنبياء يكونوا مولودين من زنا\nيعني كإن عيسى عليه السلام بيقول لهم أنا نبي.. وعبد لله... اتولدت بمعجزة، مش من الزنا.. وأمي مش زانية زي ما اتهمتوها مع إنكم عارفين أصلها وشرفها \nبل إنتم يا بني إسرائيل عارفين إن الأنبياء بيبعثوا في نَسَبِ قومِهِم، يعني بيكونوا من أشراف قومهم المعروف عنهم النزاهة وكل الأخلاق الطيبة عشان محدش يطعن في عِرضهم وشرفهم سواء ست أو راجل..\nوبالفعل علو المقام والشرف والأخلاق ده كله كان اعترف بيه بنو إسرائيل وهم بيكلموها في الأول لما قالوا لها :\n\"يا أخت هارون ما كان أبوكِ امرءَ سَوءٍ وما كانت أمك بَغِيًّا\"\nعيسى عليه السلام كَمّل تعريف بنفسه وتعريف بوصايا ربنا له، والناس واقفة مذهولة\nقال:\n\"وَجَعَلَنِي مُبَارَكًا أَيْنَ مَا كُنتُ وَأَوْصَانِي بِالصَّلاةِ وَالزَّكَاةِ مَا دُمْتُ حَيًّا\" \n\"وَأَوْصَانِي بِالصَّلاةِ وَالزَّكَاةِ مَا دُمْتُ حَيًّا\"\nيعني ربنا جعلني مبارك ومُعلم الخير للناس وداعيا إليه عز وجل ومُحَبِّبِ الناس في طاعة الله\nووصاني بالصلاة والزكاة طول ما أنا حي \n☆ممكن حد يسأل دلوقتي ويقول ..يعني عيسى عليه السلام دلوقتي بيصلي ويزكي\nيعني احنا كمسلمين عقيدتنا بتقول إن عيسى عليه السلام لم يمت وإنه هينزل في آخر الزمان..يبقى هو كده بيصلي ويزكي؟\nوكمان ليه مذكرش الصيام..مش ربنا قال إن الصيام كان مفروض على الناس إللي قبلنا \nشوفوا،\n♡أولا: عيسى عليه السلام ربنا قال على لسانه:\n\"فَلَمَّا تَوَفَّيْتَنِي كُنتَ أَنتَ الرَّقِيبَ عَلَيْهِمْ\"\nالوفاة هنا معناها النوم..لو في واحد نايم بنقول عليه حي ولا ميت\nبنقول عليه حي مع إن ربنا بيقول:\n\"اللَّهُ يَتَوَفَّى الْأَنفُسَ حِينَ مَوْتِهَا وَالَّتِي لَمْ تَمُتْ فِي مَنَامِهَا\"\nفعيسى عليه السلام دلوقتي نايم وبيصحى بأمر الله.. لما ربنا يشاء يعني،\nومن الأوقات إللي صِحي فيها كانت في رحلة الإسراء والمعراج ، لما رسول الله ﷺ صلى بالأنبياء جميعا في المسجد الأقصى،\nولما رآه رسول الله في السماء الثانية مع يحيى عليه السلام في رحلة المعراج وهنعرف الموضوع بالتفصيل واحنا بنتكلم في السيرة النبوية،\nفهو بيصحى وقت ما ربنا يريد وينام وقت ما ربنا يريد، فحكُم عيسى عليه السلام كحكم النائم ،وإنتم عارفين إن الصلاة تسقط عن النائم \nوطبعا الزكاة نفس الموضوع، واحد نايم هيجيب فلوس منين عشان تبلغ النصاب ويخرجها\n♡ثانيا:\nبالنسبة للصيام ..عيسى عليه السلام مقلش الصيام وده معناه إن ربنا تكفّل ببقاء جسده بغير طعام ولا شراب\nفهو لو قال إن ربنا أوصاني بالصيام يبقى ده يدل إنه بياكل،\nوعشان الإنسان ياكل لازم يكون صاحي مش هياكل وهو نايم يعني\nفالكلام ده معناه إنه نام وربنا هو إللي تكفّل ببقاء جسده من غير لا أكل ولا مية،\nعارفين زي إيه؟\nفاكرين قصة أصحاب الكهف إللي قلناها، وإنهم ناموا أكثر من  ثلاثمائة سنة بدون أكل أو شرب وحتى شكلهم متغيرش\nوكمان ربنا تكفّل بهم إنهم لا يمرضوا وإنهم لا يصيبهم العمى وتكفّل بحاجات كتير أوي لهم.\n◇خدوا بالكم إن اليهود والنصارى بيؤمنوا بقصة أصحاب الكهف\nفإيه المشكلة في إن ربنا يتكفل بجسد عيسى عليه السلام خلال السنين دي كلها زي أصحاب الكهف لحد ما ينزل للأرض في آخر الزمان\nفاللي يخلينا نقبل بمعجزة أصحاب الكهف نقبل بمعجزة عيسى عليه السلام، \nوخصوصا إن عيسى عليه السلام خارج نطاق الزمن أصلا؛\nلأن ربنا لما هيرفعه هيكون عمره ثلاثة وثلاثين سنة،\nولما ينزل في آخر الزمن هيكون عمره برده ثلاثة وثلاثين سنة\nيعني الإنسان بيكبر في العمر بسبب إيه\nمش بسبب تعاقب الليل والنهار؟ والسبب في تعاقب الليل والنهار هو الشمس، \nفعيسى بقى خارج المنظومة بتاعتنا دي خالص\nعيسى عليه السلام كمّل كلامه وقال:\n\"وَبَرًّا بِوَالِدَتِي وَلَمْ يَجْعَلْنِي جَبَّارًا شَقِيًّا\"\nيعني ربنا جعلني كمان بار بوالدتي ، وعصمني من إني أكون متكبر على أوامره عز وجل ولا عاصيا له ، \nوعصمني من إني أكون متكبر على البشر أقتلهم وأضربهم وأقهرهم \n◇طيب سؤال للتدبر:  ليه عيسى عليه السلام قال والدتي ومقالش أمي، مع إن لفظ الأم أعم وأقوى من لفظ الوالدة \nيعني كلمة الأم تشمل الأم إللي ولدت وإللي ربت والأم من الرضاعة وهكذا .. ليه بقى قال والدتي\nلإن عيسى عليه السلام كان عايز يثبت لهم بشكل خاص قضية محددة ويركز عليها من كل قضايا الأمومة:\nقضية إن إللي ولدته وأنجبته هي مريم عليها السلام \nفلو قال لهم أمي، ممكن يفكتروا أمه الروحية مثلا ولّا أمه إللي تكفّلت برعايته لإنه يتيم،\n فقال \"والدتي\" عشان يُثبت ويؤكد إنه اتولد من مريم رضي الله عنها مش من حد تاني\nطيب بعد المعجزة الواضحة دي،هل بني إسرائيل اقتنعوا بقى وصدقوا مريم واعتذروا لها؟\nأبداااا \nهو في ناس كده، مهما ظهر لهم الحق بمعجزات كمان، إللي في دماغهم في دماغهم\nومش عايزين يقتنعوا لأنهم ببساطة بيبقوا مّتبعين لهواهم وعايزين يشمتوا في الناس الصالحين وخلاص، حتى لو همّ عارفين ومتأكدين إنهم على حق وإن إللي اتقال عن الصالحين ده غير صحيح\nفربنا هنا بيعلمنا إننا منهتمش بكلام الناس مادام احنا صالحين وعارفين ومتأكدين إننا على حق، وإن في نوعية من الناس مهما حاولتي تقتنعهم مش هيقتنعوا \nيبقى نعمل إللي ربنا يريده منا وخلاص، لأن ربنا هو إللي هيحاسبنا في الآخرة مش الناس\n☆خلونا نتدبر الآيات كده ونشوف ليه عيسى عليه السلام قال :لم يجعلني جبارا شقيا،\nفي حين إن يحيى عليه السلام قال: لم يجعلني جبارا عصيا\nيحيى عليه السلام أمه وأبوه كانوا على قيد الحياة،\nفلو كان يحيى عاق بيعصي أوامر أمه أو أبوه، فالأم هتواسي الأب ،والأب هيواسي الأم،\nفجاء لفظ \"عصيا\" هنا مناسب لتعريف الوضع فعلا لو حصل عقوق من يحيي عليه السلام \nويحيى عليه السلام جاء للدنيا من أب وأم، هو أه جاء  بمعجزة، لكن الموضوع  لسه منطقي لبني إسرائيل؛ لإن في أب وأم وزواج طبيعي،\nفبالتالي بنو إسرائيل تقبّلوا موضوع ميلاد يحيى ومكنش في عداء بين أهله وبينهم بسبب ولادته\nلكن عند عيسى عليه السلام ومريم وضعهم مختلف زي ما شوفنا؛ لإنه جاء من أم فقط بدون أب نهائي\nفمفيش زوج أو أب يدعمها لو حصل عقوق، \nوكمان معجزة ميلاد عيسى أقوى وأصعب على القبول عند ناس عندهم النزعة المادية عالية زي بني إسرائيل كده\nفعشان كد بنو إسرائيل لم يتقبلوا معجزة خلق عيسى ببساطة، \nوكانوا كلهم ضد مريم رضي الله عنها بسبب عيسى، \nفبالتالي لو عيسى عليه السلام عَقّ مريم في يوم من الأيام، مين إللي هيواسيها وهيرحمها وهي وحيدة تماما\n  \nفجاء لفظ \"شقيا\" هنا مناسب أكتر لتعريف الوضع فعلا لو حصل عقوق من عيسى عليه السلام؛ \nلأن كلمة شَقِيّ معناها الشخص إللي نُزِعت منه الرحمة،\nفهو كده هيكون أشد في البعد عن الرحمة لو حصل منه عقوق لأمه\n◇عندنا بقى سؤال تاني مهم : هو ليه ربنا من الأساس خلق عيسى عليه السلام من أم بدون أب\nطبعا ربنا لا يُسأل عما يفعل... لكن احنا هنشوف الحكمة من خلق عيسى عليه السلام بدون أب\n♡أول سبب هو بيان قدرة ربنا\nاحنا مشوفناش خَلق آدم عليه السلام ولا خلق حواء، \nلكن سمعنا عنهم والموضوع بقى مستقر في نفوسنا فخلاص سلمنا الأمر لله،\nفربنا أراد إنه يُرينا قدرته بإنه يخلق في الدنيا طفل بدون أب،\nوإلا فخلق بشر من كومة تراب أصعب من وجهة نظرنا من خلق طفل داخل رَحِم أم، خلق محض بدون زوج\nيعني بص كده لكومة تراب وتخيل إن ده كان أصلك\nفخلق عيسى يشبه خلق آدم من الناحية دي، \nيعني من ناحية خلق الشيء من العدم تماما بدون اكتمال أسبابه، \nبل في حالة آدم مفيش أسبابه كلها أصلا، فخلق عيسى يشبه خلق آدم في حتة إن ربنا قال للإثنين كن فكان،\n\"إنَّ مَثَلَ عِيسَى عِندَ اللَّهِ كَمَثَلِ آدَمَ خَلَقَهُ مِن تُرَابٍ ثُمَّ قَالَ لَهُ كُن فَيَكُونُ\"\nلكن في حالة آدم: التراب اتحول لبشر \nوفي حالة عيسى: النفخة اتحولت لبشر \nثم هو  مين إللي بيأذن بحصول الحمل؟ مش ربنا؟ \nومين إللي هيأ الأسباب الطبيعية المعروفة إللي بيها بيحصل الحمل؟ مش ربنا؟\nطيب مش إللي جعل الطريقة الفلانية المعروفة دي لحصول الحمل، قادر برده إنه يجعل طريقة تانية لحصول الحمل \nالمشكلة بس إننا اتعودنا إن هي دي الطريقة الوحيدة للحمل، وده مش مضبوط في تعريف قدرة الله\nاحنا اتعودنا إن الجنين عشان يتكون لازم يكون فيه ذكر وأنثى.\nعارفين زي إيه مثلا ولله المثل الأعلى\nلما الناس زمان كانوا بيسافروا على الجمال وكانت دي وسيلة النقل الوحيدة عندهم ومتعودين عليها،\nفلما اخترعوا العربيات أكيد الناس استغربت في الأول وكان في ناس مترضاش تركبها لأنهم مش متعودين عليها،\nفتخيلوا مثلا لو اخترعوا سيارات بتطير فوق البيوت دلوقتي هنبقى مستغربين وقلقانين وممكن منرضاش نركبها ونخاف منها في الأول عشان مش متعودين عليها\nفربنا كسر لنا العادة دي وعمل لنا حاجة ضد إللي احنا اتعودنا عليه ده عشان يُورّينا قدرته ويؤيد رسله بالمعجزات عشان نصدق إنهم مش بشر عاديين، \nوانهم دول مُؤيدين بالقوة العظمى إللي متحكمة في سير الكون ده كله وماسكة قوانينه؛ وهو  الله عز وجل\nآه الحياة ليها قوانين عشان نعرف نعيش في أمان ونستوعب الأمور بشكل منطقي وعلمي دقيق،\nلكن لما ربنا يدلل لنا على قدرته بتغيير القوانين دي بمعجزات على يد أنبياؤه، فمنقولش ده مستحيل يحصل\nوبكده تتم القسمة الرباعية:\nخلق الله آدم بلا ذكر ولا أنثى...وخلق حواء من ذكر بلا أنثى،\nوخلق البشر من ذكر وأنثى، وخلق عيسى من أنثى بلا ذكر\nوجعل سبحانه عجوز وعقيم ينجبوا، وجعل عذراء تنجب، وجعل أصحّاء مبينجبوش..\nكل ده عشان نتعلم إن قدرة ربنا مالهاش حدود، وإنما أمره إذا أراد شيئا أن يقول له كن فيكون\n♡السبب الثاني:\nإن بني إسرائيل ناس ماديين زي ما قلنا وشوفنا.\nيعني لو شافوا بعنيهم يؤمنوا، مشافوش لا يؤمنوا\nفهمّ نشأوا عالمادة وبالغوا في المادية وطغت عليهم،\nحتى لما تلاقوا واحد بيحاسب واحد على كل صغيرة وكبيرة في أمور الماديات يقول له: إيه يا أخي انت يهودي \nفكل حاجة بالنسبة لهم كده، وكإنهم عاوزين لكل أمر إلهي ينزل معاه معجزة، \nوكإن كل أمر إلهي بينزل بيلغي المعجزة إللي قبله ولازم النبي يرجع يقنعهم من الأول كل مرة إنهم لازم يطيعوه لإنه رسول من عند ربنا!\nفاكرين لما قالوا لموسى عليه السلام أرنا الله جهرة؟\nكان السبب إنهم عاوزين إله متجسد قدامهم يعبدوه، عشان كده أول ما عبروا البحر وشافوا ناس بتعبد أصنام قالوا لموسى :\n\"اجعل لنا إلها كما لهم آلهة\"\nوطبعا في فرق بينهم وبين موسى عليه السلام لما طلب إنه يشوف ربنا\nالفرق بينهم إن موسى طلب الطلب ده من  باب الاشتياق لرؤية الله عز وجل، لكن همّ طلبوا من باب إنهم يعبدوا حاجة شايفينها مش غيبية،\nفهم نشأوا عالمادة وبالغوا في المادية وطغت عليهم ،\nفكان لازم حاجة تكسر عندهم كل شوية حتة المادية والتعلق بالأسباب الزايد عن حده ده، فإيه إللي يكسرها  المرة دي\nإرسال نبي بدون أب، ومالوش نسب معاهم، \nيعني عيسى مالوش نسب متصل ببني إسرائيل \nوكل الأنبياء كانوا ييجوا ويقولوا لقومهم \"يا قومي\"ِ إلا عيسى عليه السلام كان بيقول لهم \"يابني إسرائيل\"  \nلإن مفيش أب ينتسب من خلاله ليهم  \nبعد ما عيسى عليه السلام كلّم بني إسرائيل ووضح لهم هو مين، وبيّن لهم وصايا ربنا ليه، وبرّأ أمه من سوء ظنهم وبهتانهم، \nختم كلامه بإنه وقال:\n\"والسلام عليَّ يومَ وُلِدتُّ ويوم أموتُ ويوم أُبعَثُ حَيًّا\"\nبيقول لهم إن يوم لما اتولد ، ربنا عصمه من وَكْزَة الشيطان إللي بتحصل للمولود\n☆وإيه وكزة الشيطان دي كمان\nكل الأطفال إللي بيتولدوا الشيطان بيمسهم بنزغــة ، يعني بيطعن الأطفال بصباعه كده زي وكزة بإيده في جنبهم، بيصرخ الطفل بعدها ، وده سبب بكاء الأطفال حديثي الولادة أول ما بيخرجوا من الرحم.. لما الطفل بيصرخ ده بيكون بسبب طعنة الشيطان دي،\nوطبعا ده بيوضّح شدة العداء إللي بين الشيطان وبين بني آدم\nوالدليل حديث رسول الله ﷺ :\n\"ما من بني آدم مولود إلا يمسه الشيطان حين يُولد ، فيستهل صارخا من مس الشيطان ، غير مريم وابنها\"\nفاكرين لما اتكلمنا عن حَنة أم مريم عليها السلام وإنها قالت لما ولدت واتضح إن المولد بنت مش ولد، فقالت : وإني سميتها مريم وإني أعيذها بك وذريتها من الشيطان الرجيم؟\nأهو ربنا حمى عيسى ومريم عليهما السلام من طعنة الشيطان ببركة دعاء حنة ده،\nفلما جه الشيطان يطعن عيسى عند مولده، ربنا جعل فيه حجاب بينهم، فالشيطان طعن في الحجاب نفسه ومعرفش يوصل لعيسى عليه السلام،\nوده معنى السلام والعصمة بتاعة وقت الولادة ، زي ما جه في الآية،\nأما \"ويوم أموت\"؛ فربنا كمان أمِّنُه يوم ما هيموت، وده هيكون بعد ما ينزل عيسى عليه السلام في آخر الزمان ويقتل الدجال، ثم يقعد في الأرض زمن وبعدين يموت.. وهو ده اليوم المقصود في الآية..\nطب \"ويوم أُبعَثُ حيا\"؟\nربنا أمنه كمان يوم البعث، من إنه يصيبه إللي بيصيب الناس من الفزع لما يشوفوا أهوال يوم القيامة \n\"وَالسَّلامُ عَلَيَّ يَوْمَ وُلِدتُّ وَيَوْمَ أَمُوتُ وَيَوْمَ أُبْعَثُ حَيًّا\"\nبنو إسرائيل شافوا معجزتين :\nولادة عيسى بدون أب...وطفل رضيع تكلم ،\nفهل آمنوا وصدقوا وبرؤوا مريم عليها السلام؟\nوهل كان عيسى هو الوحيد إللي تكلّم في المهد ولّا كان في غيره؟\nده إللي هنعرفه الجزء الجاي إن شاء الله"}, {"n": 39, "l": "الحلقه ٥٧ | عيسي ٣ | والحلقه ٥٨ | عيسي ٤", "u": "https://www.facebook.com/groups/710210019782034/permalink/761195281350174/", "t": "#قصص_الأنبياء\n#الحلقة_السابعة_والخمسون   \n#مريم_زكريا_الجزء_السابع  \n#عيسى_الجزء_الثالث\n#الذين_تكلموا_في_المهد  \nوقفنا المرة إللي فاتت عند عيسى عليه السلام لما ربنا أنطقه عشان يدافع عن مريم عليها السلام وهو لسه طفل رضيع،\nوكانت معجزة واضحة لبني إسرائيل،\nمش يعتذروا بقى لمريم عليها السلام ويقولوا آمنا بالله وحقك علينا والكلام ده،\nلأ ده كذِّبُوها وقالوا لها إنها بَغِيّ، وكانوا بيسموا عيسى عليه السلام ابن البغي\n☆شوفوا على قدر مكانة مريم رضي الله عنها وقدرها عند ربنا لدرجة إنها المرأة الوحيدة إللي ربنا ذكرها في القرآن بالاسم،\nومع ذلك بتتعرض للإهانة والقذف من قومها إللي كانوا لسه بيمدحوها ومعترفين بفضلها لما قالوا \"يا أخت هارون\"\nفدي رسالة من ربنا لكل واحد فينا بإننا مهما بَلَغنا من التَّقوى والعَفاف وحُسن الخلق فمش هنسلَم من كلام الناس،\nهنلاقي إللي مستني الفرصة عشان يؤذينا ويشوّه صلاحنا.. هنلاقي إللي بيستفزنا ويقول كلام مش فينا،\nهنلاقي... وهنلاقي...\nودي رسالة للنساء بالذات\nيعني احنا كنساء عمرنا ما هنوصل لدرجة مريم عليها السلام في الكمال والفضل والمكانة؛ لإنها من النساء إللي النبي ﷺ قال عنهن: \n\"لَمْ يَكْمُلْ مِنَ النِّسَاءِ: إِلَّا آسِيَةُ امْرَأَةُ فِرْعَوْنَ، وَمَرْيَمُ بِنْتُ عِمْرَانَ\"\nومع ذلك حصل لها الإبتلاء ده ولم تسلم من كلام الناس، يبقى احنا بقى يا جماعة متوقعين إيه من الناس\n◇ممكن حد يسأل: \nطيب وهو ليه ربنا بيعمل كده..؟\nإيه الحكمة من إنه عز وجل بيسلط الناس المؤذية دي أو بيَأذن بأذى الصالحين؟ مش المفروض إنه يحميهم منهم \nشوفوا،\nأي ابتلاء بيكون يا إما لتكفير الذنوب أو لرفع الدرجات أو \nإن ربنا يريد يعلمنا عبادة قلبية مش هنتعلمها غير بالابتلاء والأذى ده،\nزي التضرع لله أو الخشوع والخضوع والذل له\nواحنا المفروض أي ابتلاء بينزل علينا نتعامل معاه على إنه تكفير لذنوبنا، طب ليه\nعشان النفس اللوامة هي إللي هتجدد التوبة باستمرار، وأي ابتلاء بيحصل لنا بيكون سبب في تكفير الذنوب\n \nرسول الله ﷺ بيقول:\n\"مَا يُصِيبُ الْمُسْلِمَ مِنْ نَصَبٍ وَلاَ وَصَبٍ وَلاَ هَمٍّ وَلاَ حَزَن وَلاَ أَذًى وَلاَ غمٍّ، حتَّى الشَّوْكَةُ يُشَاكُها إِلاَّ كفَّر اللَّه بهَا مِنْ خطَايَاه\"\nيعني أي حاجة بتصيب الإنسان من التعب أو الهم أو الحزن أوالغم أو الأذى حتى الشوكة إللي بتشك الإنسان -شكة الدبوس يعني مثلا- كووول ده ربنا بيكفر به عن ذنوب الإنسان\nوهقولكم حاجة كمان\nمن صفات أهل الجنة إنهم كانوا من الكاظمين للغيظ في الدنيا،\nيعني كانت بتحصل لهم مواقف تضايق فكانوا مع ذلك بيكتموا غيظهم وغضبهم لله ده، ومش بيقابلوا الإساءة بإساءة ولا بظلم،\nفاحنا إزاي هنعرف نكظم غيظنا ومفيش ناس مستفزة حوالينا ومفيش ناس تضايقنا أساسا، و مفيش ناس تحرق دمنا وتؤذينا بلسانها عشان ونصبر ونمارس عبادة احتساب الأجر لله على الصبر على الظلم و الأذى\nفربنا بيسمح بوجود الناس دي في طريقنا عشان نصلح أنفسنا ونصلح قلوبنا إللي هتكون التذكرة إللي هندخل بها الجنة\nربنا بيقول : \"يَوْمَ لَا يَنفَعُ مَالٌ وَلَا بَنُونَ*إِلَّا مَنْ أَتَى اللَّهَ بِقَلْبٍ سَلِيمٍ \"\nفاحنا بسبب الناس دي هنكتسب صفات جديدة ربنا بيحبها عز وجل وبتزود من قربنا منه وترفع درجاتنا عنده، \nيعني هنتعامل مثلا مع شخص عصبي، هنتعلم بسببه الصبر والحِلم،\nهنتعامل مع شخص أناني، هتعلم بسببه الحِكمة وضرورة التمسك بالكرم والإيثار مع الناس،\nهنتعامل مع شخص مستفز هنتعلم بسببه كظم الغيظ، وبعدها نطلع للدرجة الأعلى وهي العفو عن الناس، يعني مسامحة إللي ظلمهم، \nيعني همّ ملهمش خالص في قصة الثأر للنفس دي:\n\"وَإِنْ عَاقَبْتُمْ فَعَاقِبُوا بِمِثْلِ مَا عُوقِبْتُم بِهِ ۖ وَلَئِن صَبَرْتُمْ لَهُوَ خَيْرٌ لِّلصَّابِرِينَ ۩ \nوَاصْبِرْ وَمَا صَبْرُكَ إِلَّا بِاللَّهِ ۚ وَلَا تَحْزَنْ عَلَيْهِمْ وَلَا تَكُ فِي ضَيْقٍ مِّمَّا يَمْكُرُونَ ۩إِنَّ اللَّهَ مَعَ الَّذِينَ اتَّقَوا وَّالَّذِينَ هُم مُّحْسِنُونَ\"\nفدي كلها صفات ربنا بيحبها جدا وبسببها المسلم يدخل الجنة ويبقى من أصحاب الدرجات العليا عنده عز وجل\nشيخ الإسلام ابن تيمية ملخص الموضوع ده كله في كلمتين\nبيقول: إنما العباد آلة.. فانظر إلى مَن سلطهم عليك.. ولا تنظر إلى صَنِيعهم بك.. ترتاح من الهم والغم\nيعني بيقول البشر دول عاملين زي الآلات إللي بيحركهم ربنا عز وجل،\nفاحنا عشان نريح نفسنا من وجع الدماغ وحرقة الدم وقهرة النفس؛ منركزش على إللي همّ عملوا فينا،\nلكن نركز ونشوف مين إللي خلاهم يعملوا كده، وساعتها هنسلم لقضاء ربنا ونرضى لإننا عارفين إن إللي حصل ده من حكمة ربنا الحكيم العليم الرحيم عز وجل،\nوننظر لكل شخص يدخل حياتنا كأنه الخضر في حياة موسى عليه السلام جاي يعلمنا حاجة جديدة \nلكن يا جماعة مش معنى كلامي إن لما حد يضربك بالقلم على خدك تقوم تديله خدك التاني \nإطلاقا.. الإسلام إللي أمرنا بالتسامح وكظم الغيظ، هو برده إللي قال لك اردع الظالم عن ظلمه ووقفه عند حده\nفكلامي إللي فوق\n حاجة وإنك تدفع الظلم والإعتداء عن نفسك حاجة تانية، \nكل موقف بيكون له الرد المناسب بتاعه.. مش مجال تفصيله دلوقتي، لكن باختصار: الموضوع بيكون دايما محتاج توازن وده إنتم إللي تحددوه\nنرجع لعيسى عليه السلام، \nبعد المرة إللي عيسى عليه السلام تكلَّم فيها في المَهد قدام بني إسرائيل، ما اتكلمش تاني بعدها إلا لما وصل للسن العادي للأطفال بتاع الكلام،\nوطبعا بنو إسرائيل مكنوش سايبين مريم وعيسى عليهما السلام في حالهم\nده غير إنهم كانوا عايزين يقتلوا عيسى عليه السلام،\nفمريم أخدته وهربت من بيت لحم وراحت مكان معين، \nإيه هو ؟ منعرفش بالتحديد.. علماء قالوا راحت مصر وعلماء تانيين قالوا إنها راحت دمشق، وعلماء قالوا راحت بيت المقدس،\nالمهم إن ربنا اختار لمريم وعيسى عليهما السلام مكان بتتوفر فيه مقومات الحياة عشان يعيشوا فيه، زي ما ربنا قال في القرآن:\n\"وَجَعَلْنَا ابْنَ مَرْيَمَ وَأُمَّهُ آيَةً وَآوَيْنَاهُمَا إِلَىٰ رَبْوَةٍ ذَاتِ قَرَارٍ وَمَعِينٍ \"\nنشأ عيسى عليه السلام في رعاية مريم رضي الله عنها وكان واضح عليه علامات الذكاء والنّباهة، لكن مفيش أخبار مُوَثقة عن فترة شبابه إللي قبل التلاتين من عمره حصل فيها إيه،\nو لما بلغ ثلاثين سنة، ربنا أرسله كرسول لبني إسرائيل.\n☆قبل ما نكمل الأحداث في قصة عيسى عايزين نعرف هل في حد تاني تكلم في المهد ..يعني هل تكلم أطفال رُضّع غير عيسى عليه السلام \nيجاوبنا على السؤال ده رسول الله ﷺ \nقال إنه لم يتكلم في المهد إلا ثلاثة عيسى عليه السلام وعرفنا قصته،\nوالثاني غلام جُرَيْج، و الثالث إللي تكلم في المهد: رضيع امرأة بني إسرائيل.\nقال رسول الله ﷺ: \"لَمْ يَتَكَلَّمْ فِي المَهْدِ إِلَّا ثَلاَثَةٌ: عِيسَى...\"\nوالحديث ده يا جماعة هو الوحيد الصحيح،\nيعني أي حديث تاني ورد فيه غير الثلاثة دول، يا إما ضعيف أو موقوف،\nيعني طفل أصحاب الأخدود، والشاهد إللي في قصة يوسف عليه السلام إللي قالوا إنه طفل، وابن ماشطة فرعون،\nكلهم فيهم كلام\n◇خلونا نشوف قصة غلام جُرَيج.\nجُرَيج ده كان عابد من عُبّاد بني إسرائيل، كان في عهد أنهي نبي؟ منعرفش\nإللي يهمنا الموقف إللي حصل معاه..\nجريج ده كان في الأول تاجر وكان بيخسر مرة ويكسب مرة،\nففي مرة قال: \n\"التجارة دي مش نافعة \nأنا هشتغل في تجارة متخسرش أبدا! والتجارة إللي ما بتخسرش وبتكسب دايما هي عبادة ربنا، أنا هتاجر مع الله \nلإن الحسنة بعشر أمثالها والله يضاعف لمن يشاء، \nوإللي بيعمل سيئة بتتحسب له سيئة واحدة و لو معملهاش بتتكتب له حسنة تخيلوا\nده غير إن سلعة ربنا \"الجنة\" إللي فيها كل النعيم وكل العوض وكل المكسب... فهل في تجارة أربح من كده \nجُرَيْج خرج خارج البلد و بنى له صَوْمَعة من الطين وانعزل عن الناس وبقى بيتعبد فيها لله، وده كان أمر مشهور بالطريقة دي عند اليهود والنصارى،\nوالصّوْمَعة دي يعني أوضة كده مرفوعة عن الأرض، مالهاش سلم ، بيطلع فيها المُتعبد عن طريق حبل ولما يطلع يشد الحبل وراه، عشان محدش يطلع له ويزعجه، \nولما يحب ينزل يقوم منزل الحبل ونازل عليه ويشوف حاله،\nففي يوم من الأيام كان جُرَيج ده بيتعبد في الصومعة بتاعته كعادته،\nفجت أمه عنده تحت الصومعة وبدأت تنادي عليه : \nيا جريج.. يا جريج.. !\nواقفة تنادي عليه وتبص لفوق وحاطة إيدها على حواجبها عشان يعني تغطي عينها من الشمس، \nو الوصف الدقيق ده موجود في الحديث بالظبط كده حتى إن رسول الله ﷺ وهو بيحكي الحديث للصحابة مثّل لهم بإيده إزاي كانت أم جريج حاطة إيدها على عينها وهي بتنده لابنها\nو ده يورينا أد إيه إنها كانت واقفة وقفة متعبة عليها ومسببة لها ضيق وألم\nالمهم،\nجُريْج سمع والدته بتنادي عليه، وهو ساعتها كان بيصلي زي نافلة كده مش صلاة فرض يعني،\nفبقى محتار وقعد يقول في نفسه: \nأمي ولّا صلاتي؟ ..أمي ولّا صلاتي..؟ \nيعني يارب أرد على أمي ولّا أكمل صلاتي؟\nلحد ما حسم أمره في الآخر واختار صلاته وساب أمه تنادي بدون ما يرد عليها ويشوف محتاجة إيه، \nفأمه مشيت.. \nجت له تاني يوم في صومعته لحد عنده، وكان برده بيصلي ، فندهت عليه بنفس الطريقة إللي قلناها\nوبردو فضل محتار: ياربي أمي ولّا صلاتي ..؟\nأمي ولّا صلاتي..؟ فاختار صلاته زي المرة الأولى، وأمه مشيت،\nالمفروض طبعا إنه لما يخلص صلاته عشان يروح ينام مثلا أو ياكل أو يقضي حاجته؛ كان يروح لبيت أمه يشوفها كانت عاوزة إيه، لكن معملش كده للأسف\nوتالت يوم حصل نفس الموقف بالضبط واختار صلاته...\nوكل مرة أمه تمشي خايبة الرجا، وتعبانة وحزينة وقلبها مكسور،\nلكن المرة دي أمه قبل ما تمشي رفعت إيدها للسما ودعت عليه\nقالت :ياربِّ لا تُمِته حتى يَرَى وُجُوهَ المياميس أو المومسات\n☆المياميس مفردها مومس يعني المرأة البغي التي تتخذ الزنا مهنة وتتكسب منها\nوإذا أراد الله شيء وأَذِن بوقوعه، بيهيأ له أسبابه..\nيعني احنا ممكن نستغرب دلوقتي: \nإزاي يعني واحد عابد ومنعزل عن الناس في صومتعه حتى منعزل عن أمه و هيشوف وجوه النساء البغايا\nبالعقل متجيش \nلكن ربنا له أسباب بيسببها..\nخلونا نشوف ترتيب ربنا للأحداث والأسباب كانت إزاي\nجُريج كان مشهور بين الناس، فكان في مجموعة كده من بني إسرائيل قاعدين مرة في مكان فيه فِسق وفجور، زي ملهى ليلِي كده \nوبدأوا يتكلموا على جريج وصبره على العباده وإزاي إنه زاهد ومبيفكرش في الدنيا ومش مهتم لأي حد، \nمين سمعتهم \nامرأة بغي من بغايا بني إسرائيل\nقالت لهم:\nلو تحبوا أنا أقدر أفتنه لكم وأراوده عن نفسه\nفقالوا:\nماشي موافقين اعملي إللي انتِ عايزاه.. ورّينا \nراحت البَغِي لصومعة جريج، وقعدت تتعرض له عشان تفتنه بزينتها ، وهو مش معبرها خالص ولا كإنها موجودة \nمش تسكت بقى وترجع وتقول لهم ده صعب ومحصن نفسه جامد\nلأ..دوّرت على حيلة تانية،\nكان في راعي غنم معدّي، جاء وقعد في ظل الصومعة، فتعرضت له وراودته عن نفسه وأغوته وحملت من الراعي ده بطفل في بطنها،\nوبقت ماشية تقول للناس في بطني ابن جريج،\nفالناس صبروا عليها لحد ما وِلدت، وسألوها ابن مين ده قالت: ابن جريج،\nقالوا هاتوا الفؤوس.. احنا هنروح نكسر عليه صومعته الكذاب الفاسق ده.. ! \nطب والبغي؟ مش مفروض تعاقبوها هي كمان مثلا ولّا إيه النظام؟ ما علينا \nالمهم،\nكل واحد أخذ فأس، وطلعوا على صومعة جريج، وكان بيصلي في الوقت ده، \nقعدوا يكسّروا في الصومعة بتاعته من تحت،\nفلما سمع أصوات الفؤوس خرج لهم وقال لهم بتعملوا إيه\n!!\n☆إيده ده، يعني جريج بيعرف يخرج من صومعته أهه لما حس بالخطر\nطب ما كان يشوف أمه بدل ما كانت تدعي عليه كده\nقالوا له بقى: انزل يا فاجر يا فاسق يا كذاب يا اللي بتمثل علينا التدين وانت منافق \nفقال لهم : أنا عملت إيه\nقالوا له :انزل الأول واحنا نتفاهم، فنزل ، فراحوا على طول واخدينه رابطين إيده لورا بالحبل، \nوبدأوا يتخانقوا معاه يعرَّفوه هو عمل إيه وإن خلاص البغي فضحته وكشفت المستور ومش هيفيد الإنكار في شيء، وكإن البغي هي الصادق الأمين وجُريج لو دافع عن نفسه فهو الخائن الكذاب\nفأخدوه لملك القرية عشان يحاسبه،\nمين ملك القرية ده\nأبو المرأة البغي إللي عملت الحدوتة دي كلها \nوالمفروض بقى إن ملك القرية هو إللي هيحاسبه\nيعني مش كفاية إنه و نِعم الأب يعني، لا وهيبقى ونِعم الحاكم كمان\nمهازل كانت بتحصل في بني إسرائيل فعلا وحدث ولا حرج\nالمهم وهمّ ماشيين في الطريق لملك القرية، كان الناس من كل مكان بقى متجمعين وشايفين الفضيحة وعمالين يتكلموا وفيه ضجة كبيرة حاصلة.. \nوكان وسط الناس دي مييين\nالمُومِسات\nفلما شافهم عرف إن دي دعوة أمه عليه\n☆يعني جُريج سمع دعوة أمك عليه بودنه ومع ذلك منزلش جري بسرعة يقبل راسها ورجليها ويطلب منها إنها تسامحه\nواضح فعلا إن جُرَيج كان محتاج درس مؤلم جدا زي ده عشان يتعلم معنى البر\nمشيوا بجريج وهو مربوط ومذلول ومفضوح، لحد ما وصلوا لملك القرية فقال له:\nإيه إللي إنت عملته ده يا جريج\nده احنا كنا شايفينك أعبد واحد فينا لحد ما عملت عملتك وأحبلت المرأة \nيعني خليتها تحمل بولد..\n☆شوفتوا الإيمان والتقوى إللي بتشُرررر من الكلام\nيعني سياتك يا أبو البغي شايف إن إللي يعمل كده يبقى فاسق وفاجر؟ طب وبنتك سايبها كده ليه حضرتك\nالمهم، عمل إيه جريج في الموقف العصيب ده\nهل قعد يدافع عن نفسه ويقول يا جماعة معملتش حاجة، ده هي إللي جت لي وأنا معبرتهاش و...و...؟\nهو عارف إن الناس دي إللي استنت تسع شهور عشان يعملوا الفيلم ده مش هينفع معاها أي كلام\nفبكل هدوووء وثبات قال لهم: \nهاتوا لي مَية اتوضأ\nفجابوا له المية.. اتوضى وصلى ركعتين.\n☆ملحوظة:\nالأمم السابقة كان عندهم صلاة ووضوء عادي زينا، بس طريقة الصلاة والوضوء مختلفة عن إللي عندنا في الإسلام\nبعد ما جريج صلى قال هاتولي الولد،\nفجابوا الولد وهو عمره لسه يوم، فضربه بصباعه كده، زي لكزة كده\n وقال له: \nيا غلام من أبوك؟\nفنطق الطفل الرضيع وقال: الراعي.\nطبعا كلهم أصابهم الذهول\nوقعدوا يعتذروا له، وقالوا له هنبني لك صومعة جديدة طوبة ذهب وطوبة فضة، \nفقال لهم : لا ذهب ولا فضة رجعوها بس زي ما كانت وسيبوني في حالي \nوطبعا بعد الحادثة دي زادت محبتهم له وكِبِر في نظرهم وبقى له مكانة عندهم...\nلكن يفيد بإيه مكانتك وسط الناس كلها، لو قلب أمك مش راضي عليك ومكسور بسببك؟\nمش بنتكلم على إنك بار بيها وهي قاسية عليك وبتظلمك وبتجحد البر بتاعك وتنكره..\nلأ، بنتكلم عن أي أم طبيعية انت مقصر في برك بيها،\nيفيد بإيه مكانتك عند كل الناس ومكانتك في قلبها نار وألم وحسرة؟\nطبعا هو أكيد اتعلم الدرس خلاص و راضى أمه .. لكن قصته لازم تكون درس لينا احنا كمان: \nإعلى في قلوب الناس زي ما تعلى، المهم قلب أمك\nوفي نقطة مهمة عاوزين نبينها هنا:\n☆جُريج مش نبي يا جماعة، يعني مفيش وحي يقول له إن الرضيع ده هينطق لو ضربته بصباعك وسألته، \nوأكيد مكنش متوقع أصلا إن الولد هينطق لإن مش العادي إن طفل رضيع يتكلم\nلكن صدق رجاؤه في الله ورصيده الكبير عن ربنا هو إللي خلى ربنا يحقق له المعجزة دي\nهو عارف إنه بريء وإن أكيد ربنا معاه لإنه مظلوم في شرفه وعِرضه.. فهيخاف من إيه...؟\nفاكرين لما اتكلمنا في البداية عن إزاي إن البشر عاملين زي الآلات بينفذوا قدر ربنا فينا؟\nجريج كان فاهم الموضوع كله، عشان كده قرر إنه لا يوجه لهم أي كلام نهائي، ويلجأ للقهار القدير عز وجل، إللي أذن بتسلطهم عليه بالظلم، وإللي قادر وحده على رفع الظلم ده بحوله وقوته\nوكأن لسان حاله بيقول:\nانتم اتحركتم بسبب دعوة أمي عليّ إللي ربنا استجاب لها ونزل عليّ البلاء ده،\nخلاص يبقى هروح للي أنزل البلاء وأتوسل إليه إنه يرفعه.. وعشان كده طلب وضوء وقام وصلى الركعتين ودعا.. \nالموضوع بسيط جدا\nفخلّوا قصة جُريج في بالكم دايما واعملوا زيه وقت تسلط الناس عليكم بالظلم والأذى\nوعلى فكرة قصة جريج تشبه قصة مريم عليها السلام،\nربنا أنطق عيسى عشان يدافع عن أمه البريئة،\nوبرده أنطق رضيع جريج عشان يبرئه،\nمشكلتنا في اليقين وإننا بنفكر إن البشر همّ إللي بإيدهم إنهم يضرونا أو ينفعونا،\nوناسيين إن كل حاجة بقدر ربنا والمطلوب إننا أول حاجة لازم نعملها إننا نلجأ لربنا الأول وبعدين ناخد بالأسباب\nابدأوا ازرعوا اليقين جواكم واحدة واحدة،\nاعتمدوا على ربنا في كل حاجة..قبل ما تاخدوا أي قرار استخيروا..\nقبل ما تردوا على حد شتيمة استغفروا ...مش يمكن الشتيمة دي تكفير لذنب عملناه في حد تاني ونسينا فربنا بعت لنا حد يخلص مننا الذنب القديم،\nماهو احنا مخنا مش دفتر عشان نفتكر كل حاجة عملناها\nلكن في ملائكة بتكتب وربنا عالم بكل صغيرة وكبيرة،\nفخلّوا قصة جُريج في بالكم دايما واعملوا زيه وخلوا عندكم صدق لجوء لله ويقين في نصرته عشان ربنا يكافئكم زي ما كافأه\nكده خلصنا قصة جريج..\nباقي بقى قصة الرضيع الثالث إللي تكلم في المهد.. رضيع امرأة بني إسرائيل..\nكان في بني إسرائيل امراة قاعدة بترضع ابنها الصغير في يوم كده، ومنعرفش برده هي كانت في زمن أي نبي\nفا وهي بترضع ابنها عدّى من قصادها راجل راكب على فرس، وماشي في موكب مهيب وأثار الغِنى واضحة عليه ..حاجة كده فخيمة يعني\nفالمرأة انبهرت بالمنظر! وقالت يارب ابني يبقى زيه\nفالطفل ترك الرضاعة وقال : يارب ما تخلينيش زيه\n!\nورجع يرضع مرة تانية\nأكيد الأم استغربت واتفاجئت ويمكن جه في بالها إيه ده هو الصوت ده جه منين ولّا أنا بيتهيألي ولّا إيه\nالله أعلم إيه كان رد فعلها بالظبط مش موضوعنا.. لكن كملت رضاعته تاني وعدت الموضوع لإن مفيش في إيديها حاجة تعملها غير كده\nبعد شوية وهو برده بيرضع، عدى عليهم أَمَة من الإماء،\nيعني بنت مملوكة لأحد الناس.. \nعدت قدامهم والناس نازلين فيها ضرب وعمالين يقولوا سرقتِ.!. زنيتِ..! \nفالمرأة إللي بترضع ابنها قالت: يارب ابني ميكونش زيها\nفالولد ساب الرضاعة تاني وقال: يارب خليني زيها! \nورجع يرضع تاني\n!\nفالأم قالت : لأ بقى إنت إيه حكايتك \nفالطفل قال لها:\nالرجل إللي كان على الفرس، كان جبار من الجبابرة -وفي رواية إنه من أهل النار..\nوالبنت كانت مظلومة ومعملتش حاجة بالعكس أخلاقها كويسة\n☆والعبرة إللي ناخدها من القصة دي إننا مناخدش أبدا بظاهر الأمور\nممكن نتمنى حاجة واحنا شايفينها جميلة وفيها سعادتنا لكن يتضح إنها حاجة فيها شقاء لنا وشيء مذموم\nوممكن نظن سوء في حد لإن الناس بتتكلم عنه، ويطلع بعيد عن كل الشبهات أصلا، لكن خدعتنا المظاهر إللي الناس فرضتها على الموقف،\nعشان كده ربنا قال لنا: \" والله يعلم وأنتم لا تعلمون\"\nفمندعيش ولا نتمنى حاجة من أمور الدنيا بإلحاح وكإننا متأكدين إنها الخير كله، \nلإن احنا مش عارفين بالفعل إيه إللي ممكن يحصل لنا بسببها في المستقبل،\nفدايما قول يارب لو كذا فيه خير ليّ اعملهولي، زي ما قلنا قبل كده\nمعلش طولت عليكم \nإيه إللي حصل بعد ما عيسى عليه السلام بقى رسول لبني إسرائيل؟ \nده إللي هنعرفه الجزء الجاي إن شاء الله#قصص_الأنبياء\n#الحلقة_الثامنة_والخمسون\n#مريم_زكريا_الجزء_الثامن\n#عيسى_الجزء_الرابع\nاتكلمنا عن عيسى عليه السلام وإنه اتكلم في المهد وإنه نشأ في رعاية مريم عليها السلام،\nو قلنا إنهم كانوا خرجوا من بيت لحم عشان يهربوا من أذى بني إسرائيل،\nوقلنا إن عيسى عليه السلام بعد ما نطق في المهد متكلمش تاني غير لما وصل لمرحلة الكلام العادية بتاعة الأطفال،\nوقلنا إننا معندناش أي أخبار عنه قبل بعثته،\n لما قُتل يحيى عليه السلام زي ما حكينا في قصته،\nانتشر في بني إسرائيل الكفر والفجور وتجاوزوا حدود الله وفجروا، لدرجة إن ناس منهم أنكرت البعث والحساب والعقاب، وبقوا عايشين لشهواتهم وملذاتهم وبس\nفربنا أرسل لهم رسول تاني على طول وهو عيسى عليه السلام، كان عمره لما ربنا أوحى له تلاتين سنة، وربنا أنزل عليه الإنجيل:\nوإنجيل عيسى عليه السلام امتداد لشريعة موسى عليه السلام، لكن مع بعض التخفيف،\nيعني همّ كان مُحرّم عليهم حاجات في شريعة موسى عليه السلام ،فلما جاء عيسى، أحلّ لهم بعض المحرمات دي، \nطبعا بوحي من ربنا مش منه لنفسه كده\nربنا بيقول:\n\"وَمُصَدِّقًا لِّمَا بَيْنَ يَدَيَّ مِنَ التَّوْرَاةِ وَلِأُحِلَّ لَكُم بَعْضَ الَّذِي حُرِّمَ عَلَيْكُمْ وَجِئْتُكُم بِآيَةٍ مِّن رَّبِّكُمْ فَاتَّقُواْ اللَّهَ وَأَطِيعُونِ\"\nوكان بني إسرائيل في الوقت ده مشهورين بالطب،\nوكان كل نبي بييجي بمعجزات بتكون من صميم الأمور إللي المُرسل إليهم مشهورين بيها،\nيعني موسى عليه السلام لما أرسله لفرعون كان أهل مصر مشهورين بالسحر ،\nفكان من معجزاته مثلا إنه يقلب العصا حية حقيقية تاكل الحبال بتاعة السحرة، ويخرَّج إيده بيضاء من جيبه وهو أسمر أساسا، كده يعني،\nأما عيسى عليه السلام فكانت معجزاته في الناحية الطبية لأن بني إسرائيل كانوا مشهورين بالطب،\nيعني كان بيشفي الطفل إللي مولود أعمى ، وده مالوش علاج نهائي في الطب،\nوكان بيشفي الأبرص إللي عنده مرض البرص المعروف، وده كمان مالوش علاج طبي،\nوكان بيُحيِي الموتى، ودي طبعا حاجة أصل مالهاش وجود في الطب إلا بعلاج من أوشك على الموت يعني، لكن إن حد يموت وييجي طبيب يُحيِيه من القبر؛ عمرها ما حصلت قدامهم،\nوكان بيصنع من الطين شكل الطير ، وينفخ في فم التمثال ده فيتحول لطير حقيقي بيطير في السماء\nوطبعا كل ده بقدرة ربنا يا جماعة وبإذنه.. يعني ربنا هو إللي وهب عيسى عليه السلام المعجزات دي \n\"أَنِّي أَخْلُقُ لَكُم مِّنَ الطِّينِ كَهَيْئَةِ الطَّيْرِ فَأَنفُخُ فِيهِ فَيَكُونُ طَيْرًا بِإِذْنِ اللَّهِ.. وَأُبْرِئُ الأَكْمَهَ وَالأَبْرَصَ وَأُحْيِي الْمَوْتَى بِإِذْنِ اللَّهِ \"\nومع كل المعجزات دي ووضوحها، كان بنو إسرائيل بيحاولوا يتعنتوا ويعَجِّزوا عيسى عليه السلام،\nفكانوا بيسألوه : احنا عندنا أكل إيه  في بيوتنا؟ \nفيقول لهم الأكل إللي عندهم في بيوتهم، وكمان الأكل إللي هم مخزنينه\n\"وَأُنَبِّئُكُم بِمَا تَأْكُلُونَ وَمَا تَدَّخِرُونَ فِي بُيُوتِكُمْ إِنَّ فِي ذَلِكَ لآيَةً لَّكُمْ إِن كُنتُم مُّؤْمِنِينَ\"\nعيسى عليه السلام فضل يدعوهم ويوعظهم، ويشرح لهم الحاجات إللي اختلفوا عليها، وجاء توضيحها في الإنجيل،\nلإن التوراة زي ما قلنا اتحرقت واتحرّفت بعد موسى، فربنا نزّل عليهم كتاب جديد،\n\"وَلَمَّا جَاءَ عِيسَىٰ بِالْبَيِّنَاتِ قَالَ قَدْ جِئْتُكُم بِالْحِكْمَةِ وَلِأُبَيِّنَ لَكُم بَعْضَ الَّذِي تَخْتَلِفُونَ فِيهِ ۖ فَاتَّقُوا اللَّهَ وَأَطِيعُونِ \"\nوربنا أجرى على إيده معجزات كتيرة زي ما شوفتوا، ومع ذلك بنو إسرائيل لم يؤمنوا بردو كالعادة\nفلما عيسى عليه السلام خلاص شاف منهم الكفر الواضح وإنهم معندهمش أي استعداد للإيمان طرح سؤال على الناس كلها وقال:\nمين ينصرني ويؤمن بي وبرسالة رب العالمين ويبقى معايا على الحق ؟\nربنا بيقول:\n\"فَلَمَّا أَحَسَّ عِيسَى مِنْهُمُ الْكُفْرَ قَالَ مَنْ أَنصَارِي إِلَى اللَّهِ \"\nقال مجموعة من بني إسرائيل عددهم حوالي اثنا عشر رجل احنا هننصرك ونؤيدك ونؤمن بك\nودول اسمهم الحواريين، يعني الناصرين لعيسى عليه السلام، \nأو لأنهم آمنوا بالله وكانت قلوبهم مُخلصة ونقية وصافية من العيوب والأمراض، إللي هو تعريف الحواريّ.\nربنا بيقول:\n\"قَالَ الْحَوَارِيُّونَ نَحْنُ أَنصَارُ اللَّهِ آمَنَّا بِاللَّهِ وَاشْهَدْ بِأَنَّا مُسْلِمُونَ\"\n☆متخيلين من مئات الآلاف من بني إسرائيل آمن لعيسى ١٢ رجل فقط\nعشان لما حد يقولك : يعني الناس دي كووولها غلط وانت بس إللي صح\nولّا واحد يييجي يقولك ما هو لو كان كلامك صح كان ناس كتير عملوه \nقولوا للجماعة دول بقى إن أتْباع الرسل دايما ناس قليلة، و أتباع الحق دايما ناس قليلة، \nرسول الله ﷺ قال:\n\"يأتي النبي يوم القيامة ومعه الرجل والنبي ومعه الرجلان والنبي وليس معه أحد\"\nيعني في أنبياء لم يؤمن معاهم أصلا غير رجل واحد أو رجلين، أو محدش آمن خالص\nهل ده معناه بقى إن النبي ساعتها كان هو إللي غلط عشان محدش اتبع كلامه فبقى لوحده من غير مؤمنين؟ \nلأ طبعا\nالحق عمره ما بيتقاس بالكثرة \nوخدوا التقيلة بقى، ربنا لم يذكر الكثرة في القرآن إلا وذم فيها \nشوفوا الآيات دي كده:\n\"ولكن《أكثر》 الناس لا يشكرون\"\n\"وإن《كثيرا》 من الناس لفاسقون\"\n\"وإن تطع《أكثر》 من في الأرض يضلوك\"\n\"وإن《كثيرا》 ليضلون بأهوائهم بغير علم\"\n\"ولكن《أكثر》 الناس لا يؤمنون\"\n\"وما《أكثر》 الناس ولو حرصتَ بمؤمنين\"\n\"قل لا يستوي الخبيث والطيب ولو أعجبك 《كثرة》 الخبيث\"\nوغيرها وغيرها من الآيات\nفي حين إن ربنا مدح الناس القليلة قال:\n\"و《قليل》 من عبادي الشكور\"\n*\"وَإِنَّ كَثِيرًا مِّنَ الْخُلَطَاءِ لَيَبْغِي بَعْضُهُمْ عَلَىٰ بَعْضٍ إِلَّا الَّذِينَ آمَنُوا وَعَمِلُوا الصَّالِحَاتِ وَ《قَلِيلٌ》 مَّا هُمْ \"\nحتى عمر بن الخطاب رضي الله عنه سمع واحد بيدعي وبيقول اللهم اجعلني من عبادك القليل، فعمر سأله :\nهمّ مين العباد القليل دول\nفالرجل قال له:\nدول إللي ربنا قال عنهم: \"وقليل من عبادي الشكور\" \nوما أجمل عبارة ابن القيم رحمه الله لما قال:\n\"عليك بطريق الحق ولا تستوحش 《لقِلة》 السّالكين، وإياك وطريق الباطل ولا تغتر 《بكثرة》 الهالكين\"\nفلو انت لوحدك بتعمل الصح ، ومعاك الدليل من القرآن والسنة ، فاثبت ومتتهزش بكلام الناس ولا قلة عدد الصالحين \nفعيسى عليه السلام لم يؤمن معاه إلا الـ ١٢ رجل دول، \nواتعرفوا بالحواريين زي ما قلنا من شوية،\nوالحواريون كانوا على درجة عالية من قوة الإيمان \nهمّ إللي قالوا:\n \"رَبَّنَا آمَنَّا بِمَا أَنزَلْتْ وَاتَّبَعْنَا الرَّسُولَ فَاكْتُبْنَا مَعَ الشَّاهِدِينَ\"\nوعيسى عليه السلام سُمي المسيح –نسبة للفعل \"يسيح\"، إللي هو السياحة في الأرض يعني- لإنه كان بيرتحل في الأرض مالوش مكان محدد بيقعد فيه، \nوقيل إن سبب التسمية حاجة تانية خالص، إن قدمه كانت ممسوحة يعني حتة واحدة.. والله أعلم..\nوكانت مدة بعثة عليه السلام في الأرض ثلاث سنين فقط، ثم بعدها رُفع إلى السماء،\nوقبل ما نتكلم عن موضوع الرفع ده، هنقول قصتين حصلوا مع عيسى عليه السلام ومع الحواريين\n القصتين دول من الإسرائيليات اللي قال عنها رسول الله ﷺ  حدثوا عن بني إسرائيل ولا حرج،\nواحنا وضحنا معنى الإسرائيليات وحكمها قبل كده في الجزء الخامس لو تفتكروا\nفهنقول القصة من باب العبرة وخصوصا إن المعنى بتاعهم موجود زيه عندنا في القرآن وأحاديث رسول الله ﷺ \n◇القصة الأولى: هي قصة عيسى عليه السلام مع صاحب الرغيف.\nالقصة بتقول إن عيسى عليه السلام خرج في يوم من الأيام مع رجل من بني إسرائيل، وكان الرجل معاه ثلاثة أرغفة،\nفقال لعيسى عليه السلام: رغيف ليك ورغيف ليا.\nوبعد شوية نام عيسى عليه السلام، فلما صحي ملقاش الرغيف الثالث، \nفقال لصاحبه :فين الرغيف الثالث\n؟!\nفالراجل قال له: معرفش\n!\nفسكت عيسى.. وبعدها قام جاب غزال ودبحه وشواه، ثم أكلوا منه همّ الإتنين وماتبقاش من الغزال إلا العضم،\nفعيسى عليه السلام قال للغزال: قُم!\nفالعضم اتحول لغزال من تاني بإذن لله،\nيعني رجعت له الحياة تاني بلحمه وجلده وكل شيء وقام يتحرك قدامهم\nفبعدها سأل عيسى عليه السلام الرجل تاني، وقال له:\nأستحلفك بإللي أحيا الغزال ده بعد ما أكلناه في بطننا تقول مين إللي أكل الرغيف التالت\nفالرجل قال: معرفش\nفسكت عيسى عليه السلام.. ومشيوا همّ الاتنين مع بعض،\nفوصلوا لمكان فيه ثلاثة جبال، لكن مش الجبال المعروفة الضخمة بتاعتنا دي،\nلأ المقصود يعني كومة من الصخور عالية شوية،\nزي ما تيجي تقولي  كده أنا النهاردة عندي جبل مواعين أو جبل من الغسيل، أهه نفس المعنى كده\nالمهم عيسى عليه السلام حَوِّل الكومات الصخرية التلاتة دول لذهب\n!\nوقال للرجل: واحد لي وواحد لك، والتالت للي أكل الرغيف..\nفهنا الراجل قال له: انا إللي أكلت الرغيف\n..\nفعيسى عليه السلام قال له: إنت مفيش خير من صحبتك ، فلا خير في صحبة كذاب أكيد.. \nوسابه ومشي.. \nوطبعا عيسى عليه السلام كان يعلم إن الرجل كذاب، لكنه كان عاوز يعلمه درس بكل ده، \nجاء ثلاثة رجال من قطّاع الطّرق وشافوا الرجل ومعاه الذهب فراحوا قاتلينه وأخذوا الذهب،\nلقوا نفسهم جعانين، بعتوا واحد منهم يجيب لهم أكل،\nفالإثنين قاعدين مع بعض واحد منهم قال : ما تيجي نقتل صاحبنا ونقسم الذهب ده بالنص\nفالتاني وافق واتفقوا إنهم يقتلوا صاحبهم التالت لما يرجع بالأكل..\nفي نفس الوقت ده كان صاحبهم التالت ده وهو بيشتري الأكل عمال يفكر: هو أنا ليه مأقتلش أصحابي وآخد الدهب ده كله لنفسي\n!\nفراح مشتري سِم وحطه لهم في الأكل \n \nوأول ما رجع لأصحابه، قاموا عليه قتلوه\nوقعدوا بقى ياكلوا وفرحانين بالغنيمة إللي زادت بموت صاحبهم، ولعلهم كانو بيخططوا هيعملوا إيه بالذهب وكل واحد بيقول أمانيه\nوفي وسط ده كله فجأة بدأ المغص يشتغل وملحقوش يتهنوا بالدهب ولا حتى الأكل، وماتوا بالسم إللي كان صاحبهم واضعه لهم في الأكل..\nفكلهم قتلوا بعض، وفي النهاية الكل مات، من أول الكذاب لحد قطاع الطرق.. واتبقى الدهب محدش اتهنى بيه زي ما  كان بيطمع كل واحد فيهم لدرجة إن طمعه خلاه يعصي ربنا\n \nفمر عليهم عيسى عليه السلام وكان معاه الحواريين ..فشاور لهم على الجثث والدهب، وقال: \"هذه الدنيا فاحذروها\"\nيعني الناس كلها عايزة الدنيا وبيقتلوا بعض عليها، وفي الآخر كلهم هيموتوا ومحدش هياخد من الدنيا حاجة\n☆الطمع في الدنيا وفي لذاتها بيخلينا نقع في المعاصي،\nالبنت إللي بتتبرج وبتسمع الأغاني وبتعمل ما بدا لها بتعمل كده ليه؟\nمش عشان طمعانة في لذة الدنيا .. لذة سماع الأغاني ولذة اتباع الهوى.. ولذة الكلام إن يتقال عليها إنها جميلة و...و...\nالربا إللي الناس بتتعامل بيه، مش عشان شهوة الطمع في المال وإنه يزيد،؟\nكوووول الناس دول وغيرهم هيموتوا ويسيبوا الحاجات دي وراهم،\nالبنت هتسيب لبسها الفاضح وأدوات الزينة والعطور إللي كانت بتخرج بيها من بيتها أمام الرجال و...و..\nوالرجل هيسيب الأموال والعقارات والعربيات و...و...\nالنهاية هي الموت ...أو بشكل أدق: خلونا نقول إن البداية هي الموت\nوكل حاجة طمعنا فيها وكانت سبب في إننا نقع في معصية ربنا، هنُسأل عنها يوم القيامة..\nحتى الكلمة حتى النظرة، فمفيش حاجة هتنجينا بعد رحمة الله غير التقوى والعمل الصالح؛\nتقوى الله باتقاء فتن الدنيا وتجنب الوقوع في المعاصي بسبب الجري ورا شهواتنا، \nزي ما رسول الله ﷺ وصانا:\n \"إن الدنيا حلوةٌ خضرةٌ، وإن اللهَ مستخلفُكم فيها فينظرُ كيف تعملون، ((فاتقوا)) الدنيا...\"\nوقال ﷺ:\n\"اعملوا فكل مُيسّر لما خُلق له\"\nمحدش عارف الموت هييجي امتى ولا إزاي واحنا شايفين موت الفجأة منتشر إزاي وخصوصا بين الشباب،\nفالحقوا نفسكم بجد..إللي لسه مبدأش ياخد خطوات إنه يصلح نفسه ياخد،\nإللي أخذ خطوات يزوّد ويجاهد نفسه..شوف عايز تموت إزاي وعلى إيه وزوّد منه\nعايز تموت وانت ساجد صلي كتير ...عايز تموت وانت بتقرأ قرآن يبقى تقرأ قرآن كتير وتسمع كتير،\nمن عاش على شيء مات عليه..ومن مات على شيء بُعث عليه\nتحب يوم القيامة تيجي وانت بتعمل معصية والناس كلها تشوفك وهتبقى فضيحة؟\nولّا تحب تيجي يوم القيامة وانت بتعمل طاعة وتبقى كرامة وفرحة ليك وسط الناس كلها يوم القيامة...اختر لنفسك وخليك من عباد ربنا القليل\n◇القصة التانية من كتاب بحر الدموع لابن الجوزي رحمه الله.. \nالقصة بتقول إن عيسى عليه السلام كان ماشي في مرة مع الحواريين، فعدّوا على قرية، \nفلقوا أهل القرية كلهم أموات، ومش بس كده ده كانوا مرميين في الطرق كده!\nفعيسى عليه السلام قال للحواريين إن الناس دي ماتت بسبب سَخَط وغضب من ربنا عليهم، \nلأنهم لو ماتوا عادي زي ما الناس بتموت كانوا دفنوا بعض، لكن دول ماتوا بإهلاك عام!\nفالحواريين ردوا عليه وقالوا: عايزين نعرف قصتهم إيه.!\nفدعا عيسى عليه السلام ربنا إنه يخبره بقصتهم،\nفربنا أوحى له إن لما ييجي الليل نادي عليهم وهيجاوبوك\nفلما جاء الليل طلع عيسى عليه السلام على حتة مرتفعة ونادى عليهم وقال: يا أهل القرية!!\nفجاوبه واحد منهم وقال له : لبيك يا روح الله!\nفعيسى عليه السلام قال: كنا عايزين نعرف إيه إللي حصل معاكم، إيه قصتكم؟\nفالراجل قال:\nنمنا في عافية ومكانش في دماغنا حاجة زي كل يوم، ثم أصبحنا لقينا نفسنا في النار،\nفسأله عيسى عليه السلام : وليه كده، إيه السبب\nالرجل رد وقال: \nبسبب حبنا للدنيا، وكنا بنطيع أهل المعاصي، ومكناش بنأمر بمعروف ولا بننهى عن منكر \nفعيسى عليه السلام سأل :وإزاي يعني كان حبكم للدنيا ده؟\nفالرجل أجاب:\nزي الطفل إللي بيحب أمه بالضبط.. إذا جاءت الدنيا فرحنا، وإذا تولّت عنا وابتعدت أصابنا الحزن وبكينا \nفعيسى عليه السلام قال له:\nطيب ليه انت الوحيد إللي جاوبتني، وأصحابك محدش منهم جاوبني؟\nرد وقال: باقي أهل القرية متقيدين ومربوطين بقيود من نار، وإللي مقيّدهم كده ملائكة غلاظ شداد\nفسأله عيسى عليه السلام : \nواشمعنى انت إللي جوابتني \nفقال الرجل : 《كنت  فيهم  ولم أكن  معهم》\nيعني كنت بشوف إللي بيعملوه ومش بتكلم ولا بعمل زيهم،\nفلما نزل بهم العذاب لحقني معهم،\nفأنا دلوقتي متعلق على حافة جهنم ..على طرفها ..مش عارف هل سأنجو منها ولّا هقع فيها\n☆فاكرين لما اتكلمنا عن قصة أصحاب السبت وإنهم انقسموا إلى ثلاثة أقسام :\nناس عملت المنكر ودول ربنا عذبهم وناس سكتت متكلمتش ودول محدش يعرف ربنا عمل فيهم إيه،\nوالفرقة الثالثة إللي أمرت بالمعروف ونهت عن المنكر ودي الفرقة إللي ربنا نجاها،\nأهه القصة دي شبيهة بجزاء قصة أصحاب السبت،\nوإللي قلنا العبرة من القصة ساعتها، إنك لو عايز تنجو نفسك لازم تأمر بالمعروف وتنهى عن المنكر على قدر استطاعتك ..ومتقولش ماليش دعوة أنا مبعملش زيهم، وهمّ إللي هيتحاسبوا  لوحدهم و..و...و.. إوعى..\nربنا بيقول: \n\"وَاتَّقُوا فِتْنَةً لَّا تُصِيبَنَّ الَّذِينَ ظَلَمُوا مِنكُمْ خَاصَّةً\"\n يعني احذروا واجتنبوا عذاب يوم لما هينزل مش هيصيب أهل المعاصي لوحدهم بشكل خاص فقط،\n لأ.. مش معنى إنك مبتعملش المنكر إن مش هيصيبك العذاب معاهم لو انت مكنتش بتؤمرهم بالمعروف وتنهاهم عن المنكر على قدر استطاعتك \nزينب زوجة رسول الله ﷺ سألته:\nيا رسول الله أنهلك وفينا 《الصالحون》؟\nقال نعم ..إذا كثُر الخبث\nوربنا بيقول :\n\"وَمَا كَانَ رَبُّكَ لِيُهْلِكَ الْقُرَىٰ بِظُلْمٍ وَأَهْلُهَا مُصْلِحُونَ\"\nشوفتوا الفرق؟\nلو الناس مُصلحون يعني بيصلحوا ما يفسده الناس، وبيؤمروا بالمعروف وبينهوا عن المنكر فدول ربنا مش هيهلكهم، وأصلا ساعتها المجتمع مش هيكثُر فيه الخَبَث،\nلكن لو بس صالحين كده في نفسهم وخلاص وبيشوفوا المنكر ومش بيتكلموا مع إنهم مش بيلقدوه؛ \nوكمان بيُظهروا الحب لأهل المعاصي ويتصوروا معاهم عادي ولا كإنهم ناس بتحارب ربنا ليل نهار بالعصيان والتمرد على أوامره والمجاهرة بالمعاصي دي،\nفالناس السلبيين دول مصيرهم -إن مكنوش مع أهل المعاصي نفسهم فهيكون مصيرهم على الأقل زي الراجل ده إللي قال عن نفسه \"كنت فيهم.. ولم أكن معهم\"\n¤ملحوظة هاااامة عشان كلامي ميتفهمش غلط\nأنا بتكلم عن 《أهل المعاصي》\nيعني ناس معروفين كده بالذنوب والخطايا والآثام ..غرقانين فيها ومجاهرين بها وبيظهروها قصاد الناس،\nوالقصة نفسها فيها كلمة 《أهل》\nفالفيصل هنا كلمة أهل \nمش بتكلم عن الإنسان العاصي لأننا كلنا أصحاب معاصي سواء صغيرة أو كبيرة،\nوكل بني آدم خطّاء...لكن في فرق بين واحد بيعصي ويتوب ونفسه ربنا يتوب عليه،\nوواحد غرقان في المعاصي ومجاهر بها وبيتبجح بالمعاصي  ومش فارق معاه أي حاجة خالص \nأظن كلامي واضح أهه...ماشي\nفي يوم من الأيام الحواريين سألوا عيسى عليه السلام سؤال عجيب جدا \nهنعرف السؤال إن شاء الله الجزء الجاي وإزاي جاوب عليهم عيسى عليه السلام\nhttps://www.facebook.com/groups/710210019782034/?ref=share"}, {"n": 40, "l": "الحلقه ٥٩ | عيسي ٥ | والحلقه ٦٠ والأخيره | عيسي ٦ | رفع عيسي للسماء", "u": "https://www.facebook.com/groups/710210019782034/permalink/761212684681767/", "t": "#قصص_الأنبياء\n#الحلقة_التاسعة_والخمسون\n#مريم_زكريا_الجزء_التاسع\n#عيسى_الجزء_الخامس\nوقفنا المرة إللي فاتت عند الحواريين لما سألوا عيسى عليه السلام سؤال غريب.. قالوا إيه..؟\n\"إذْ قَالَ الْحَوَارِيُّونَ يَا عِيسَى ابْنَ مَرْيَمَ هَلْ يَسْتَطِيعُ رَبُّكَ أَن يُنَزِّلَ عَلَيْنَا مَائِدَةً مِّنَ السَّمَاء \"\nيعني ياعيسى هو ربك يقدر إنه ينزل علينا مائدة من السماء \n☆بالضبط كده زي ما قرأتم، مائدة\nعايزين ترابيزة عليها أكل  تنزل لهم من السماء\nعيسى عليه السلام قال لهم : اتقوا الله\nإزاي تطلبوا حاجة زي كده والمفروض إنكم مؤمنين\n\"قَالَ اتَّقُواْ اللَّهَ إِن كُنتُم مُّؤْمِنِينَ\"\nمتسألوش الأسئلة دي وتطلبوا كل شوية آية ومعجزة، عشان مينزلش عليكم العذاب.. كفاية المعجزات إللي شفتوها لحد دلوقتي\n☆فاكرين ثمود قوم صالح\nلما طلبوا معجزة الناقة زي ماكانوا عايزين بالضبط وزي ما وصفوها وبعدين كفروا برده فربنا عذبهم \n¤ممكن هنا حد يسأل: \nهو مش المفروض إن الحواريين أصحاب عيسى عليه السلام دول هم المؤمنين المخلصين إللي على أعلى درجة من الإيمان؟\n إزاي بقى يشُكّوا في قُدرة ربنا ويسألوا عن قدرة ربنا، وكمان بصيغة \"هل يستطيع ربك\" وكأنه هو رب عيسى عليه السلام بس ومش ربهم إللي بيعبدوه\nهوّ السؤال هنا يا جماعة مكنش سؤال استفهامي ومستنيين إجابة عليه بأيوة أو لأ، \nلكن السؤال هنا كان لغرض إنهم يزدادوا إيمانا، زي إبراهيم عليه السلام لما طلب من ربنا إنه يشوف إزاي عز وجل بيحيي الموتى،\nأو إن سؤالهم بالطريقة دي كان من باب التأدب مع الله مش الشك في قدرته، \nيعني زي مثلا ولله المثل الأعلى لما يكون حد فينا معزوم عند حد وعايش دور الكسوف شوية\nفنقول لأي حد من الناس إللي احنا عندهم: \nتقدر تجيبلي مناديل؟ \nأو تقدر تجيبلي كوباية مية؟\n هو يقدر أكيد، واحنا معندناش شك في ده،\nلكن احنا لما طلبنا الحاجة بعِدنا عن أسلوب الأمر إللي هو: هات لي كوباية مية..  من باب الأدب يعني\nفالحواريين استعملوا الأدب مع ربنا لما سألوا عيسى عليه السلام،\nوقالوا هل ربك يستطيع إنه ينزّل علينا مائدة من السماء؟ يعني بدل ما يقولوا أنزل علينا مائدة من السماء؛ خلوها زي عَرض يا إما يُقبل أو لا يُقبل\nفلما عيسى عليه السلام تخيل إن ده سوء أدب منهم أو شك منهم، وقال لهم اتقوا الله؛ بدأوا يوضحوا وجهة نظرهم وقالوا:\nاحنا جعانين وعايزين ناكل فدي فرصة مناسبة لكده،\nوكمان بالمرة نطمن بآية جديدة تخص استجابة ربنا لدعاءك وإنك فعلا رسول من عنده ومش بتكذب علينا، \nيعني لما تدعي ربنا بحاجة احنا إللي اقترحناها عليك ونشوف إن ربنا عز وجل استجاب لك؛\nاحنا كده هنبقى مطمنين أكتر إنك صادق بإنك نبي مقرب منه عز وجل\nكمان الناس بتكذّبك ياعيسى فاحنا هنشهد عندهم ونقول لهم إنك حققت لنا معجزة جديدة زي ما طلبنا بالضبط، معجزة مختلفة عن معجزاتك الطبية المعروفة\n\"قَالُواْ نُرِيدُ أَن نَّأْكُلَ مِنْهَا وَتَطْمَئِنَّ قُلُوبُنَا وَنَعْلَمَ أَن قَدْ صَدَقْتَنَا وَنَكُونَ عَلَيْهَا مِنَ الشَّاهِدِينَ\"\n☆يعني عيسى عليه السلام لما كان بيَشفي الأعمى مكنتش حاجة مقنعة بالنسبة لهم، \nولما كان بيحيي الموتى ويشفي الأبرص بإذن الله و...و... ده برده مكنش حاجة مقنعة  كفاية، لكن الأكل هو إللي هيقنعهم بقى \n☆بالمناسبة ...عقيدة النصارى في إن عيسى عليه السلام كان إله أو ابن إله مكنتش موجودة إطلاقا في وجود عيسى عليه السلام،\nوانتم شفتم الحواريين بيقولوا إيه، بيقولوا :\n \"ربك\" مقالوش أباك الذي في السماء والكلام ده\nوالآية إللي ربنا بيقول فيها:\n \"وَإِذْ قَالَ اللَّهُ يَا عِيسَى ابْنَ مَرْيَمَ أَأَنتَ قُلْتَ لِلنَّاسِ اتَّخِذُونِي وَأُمِّيَ إِلَٰهَيْنِ مِن دُونِ اللَّهِ\"\nدي مش في الدنيا، السؤال ده ربنا هيسأله لعيسى عليه السلام في الآخرة من  باب إنه يُشهده على أمته إللي كفرت بالله عز وجل من بعده\nعيسى عليه السلام بدأ يدعي ربنا إنه ينزل عليهم المائدة إللي طلبوها،\nوربنا ذكر الدعاء إللي عيسى عليه السلام دعاه بالنص، مع إنه كان ممكن عز وجل يقول \"ودعا عيسى ربه \"وبس كده، لكن معنى إن ربنا أخبرنا بالدعاء بألفاظه يبقى ده معناه إن ربنا《يريد》 إنه يقول لنا رسالة \n☆بالمناسبة يا جماعة..مينفعش نقول ربنا 《عايز》 نقول ربنا 《يُريد》 كذا، لأن كلمة عِوَز في اللغة العربية بتدل على الحاجة وضيق الحال،\nفمينفعش نستخدم كلمة زي كده مع رب العالمين حتى لو منقصدش المعنى السيء\nأنا عارف إنها كلمة بتتقال كده واتعودنا عليها،\nلكن لازم نتأدب مع ربنا ونستعمل الألفاظ إللي تليق به، \nهو لو واحد فينا بيتكلم مع مديره في الشغل ولا بيتكلم مع حد في مركز عالي هيتكلم معاه كده بأيّ كلام ولّا هيستعمل الكلام المناسب\nأهه ربنا أحق إننا نتكلم معاه بأدب \nنرجع للرسالة إللي ربنا 《يريد》 إنه يوصلها لنا من خلال دعاء عيسى عليه السلام\n\"قال عيسى بنُ مريم اللَّهُمَّ رَبَّنَا أَنزِلْ عَلَيْنَا مَائِدَةً مِّنَ السَّمَاء تَكُونُ لَنَا عِيداً لِّأَوَّلِنَا وَآخِرِنَا وَآيَةً مِّنكَ وَارْزُقْنَا وَأَنتَ خَيْرُ الرَّازِقِينَ\"\nربنا بيقول لنا تعلموا من الأنبياء وبيعلمنا من خلال عيسى عليه السلام إزاي ندعوه ،\nمش بس نقول يارب احنا عايزين كذا وكذا مجرد كلام وخلاص\nعيسى عليه السلام مقلش يارب أنزل علينا مائدة من السماء وخلص الموضوع،\nلأ، ده قعَد يفَصّل في الغاية إللي هتحصل لما ربنا يستجيب الدعاء،\nوإللي كان من ضمنها إن اليوم ده هيكون يوم عيد لينا يعني هيبقى يوم مشهود...يوم عظيم..\nفكإنه بيقول لربنا: يارب لما تعطينا نعمة من نعمك فاحنا هنشكرها ومش هننساها،\nوهنوصي حتى الأجيال إللي هتيجي من بعدنا إنهم يفتكروها ويشكروا نعمتك للأبد.. \nوكمان تبقى علامة منك يارب للحواريين ولكل الناس إني صادق وإني مُؤيد منك بقوة،\nواحنا يارب منستغناش عن رزقك ومحدش بيرزقنا غيرك، فارزقنا وأنت خير الرازقين\nفعيسى عليه السلام بيختار الألفاظ وهو بيدعي ربنا، وكمان مُنكسر لله في الدعاء؛\nلإن كل ما كان الإنسان منكسر لله وعنده خشوع وتذلل صادق لله في الدعاء، كل ما كان استجابة الدعاء أسرع\nوحتى عمر بن الخطاب رضي الله عنه قال: \n\"أنا لا أحمل هم الإجابة ولكن أحمل هم الدعاء\"\n☆ممكن حد يقول طيب أنا بكون منكسر وبدعي بخشوع وبعمل كل ده بس مفيش استجابة \nاحنا قلنا قبل كده إن أي دعاء بندعيه ربنا بيستجيبه ١٠٠% لكن الإستجابة بتختلف يا إما بناخده حسنات يوم القيامة،\nأو ربنا يحققه لنا زي ما دعينا بالضبط، أو ربنا يبعد عننا مصائب على قدر ما دعينا\nمش هعيد الكلام تاني ممكن ترجعوا له في قصة الأعمى والأبرص والأقرع\nلكن في نقطة تانية وهي إن ممكن دعائنا أصلا ربنا لا يستجيبه بسبب موانع ، يعني في حاجة اسمها موانع استجابة الدعاء\nزي واحد بياكل حرام..فلوسه فيها ربا..بياكل أموال الناس بالباطل ..بيسرق ...فده ربنا لا يستجيب له\nزي ما الصحابي قال عن رسول الله ﷺ:\n\"ثُمَّ ذَكَرَ رسول الله ﷺ  الرَّجُلَ يُطِيلُ السَّفَرَ أَشْعَثَ أَغْبَرَ يَمُدُّ يَدَيْهِ إِلَى السَّمَاءِ:\n يَا رَبِّ يَا رَبِّ، وَمَطْعَمُهُ حَرَامٌ، وَمَشْرَبُهُ حَرَامٌ، وَمَلْبَسُهُ حَرَامٌ، وَغُذِيَ بِالْحَرَامِ، فَأَنَّى يُسْتَجَابُ لِذَلِكَ؟!\nواحد تاني سايب الأمر بالمعروف والنهي عن المنكر وعايش بمنطق وأنا مالي ..دع الخلق للخالق..كل واحد حر..شايف المنكر قصاده وهو عادي ومش بينكره حتى بقلبه\nده برده ربنا لا يستجيب له،\nقال رسول الله ﷺ :\n\"والَّذي نَفسي بيدِهِ لتأمُرُنَّ بالمعروفِ ولتَنهوُنَّ عنِ المنكرِ أو ليوشِكَنَّ اللَّهُ أن يبعثَ عليكُم عقابًا منهُ ثمَّ تَدعونَهُ فلا يَستجيبُ لَكُم\"\nواحد ثالث مستعجل كل شوية يقول دعوت ودعوت وربنا مستجبش لي\nقال رسول الله ﷺ:\n\"يُسْتَجابُ لأحَدِكُمْ ما لَمْ يَعْجَلْ، يقولُ: دَعَوْتُ فَلَمْ يُسْتَجَبْ لِي.\"\nواحد غيره بيدعي وهو بيجرّب ..يشوف هل ربنا هيستجيب دعاؤه ولّا لأ، وغير إللي بيدعي وهو عنده شك في استجابة ربنا لدعاؤه و....و...\nالكبسة بقى إن الواحد يبقى فيه كل موانع استجابة الدعاء وبعدين ييجي في الآخر ويقول:\nهو فين بقى ادعوني استجب لكم\nهو فين أجيبُ دعوة الداع إذا دعانِ\nويوصل لمرحلة معينة بسبب عدم استجابة دعاؤه يقول: وهو فين ربنا بقى من إللي أنا فيه ده\nوهو السبب أصلا في إللي هو فيه...مش بيكلف نفسه يتعلم ..\nمش بيكلف نفسه يسأل...\nمش بيكلف نفسه يغير عشان دعاؤه يُستجاب...عايز يعيش الدنيا على هواه بالطول والعرض وكمان عايز الآخرة..طب إزاي \nفلما ندعي ونلاقي استجابة الدعاء تأخرت نراجع نفسنا ونشوف هل في موانع لاستجابة الدعاء ولا كله تمام \nلو كله تمام يبقى عندنا بشارة إن دعاءنا مستجاب في الدنيا أو الآخرة من الثلاثة إللي قلنا عليهم من شوية\nطيب عندنا أي مانع نعمل إيه ..على طول نصلح ونغير \n◇الكلام قاعدة عاااامة \nمحدش ياخد الكلام على نفسه ويفسره غلط وبعدين يقولي انتِ قلتِ و عيدتي\nالمهم،\nربنا استجاب لعيسى عليه السلام، وطمنه إنه هينزل المائدة عليهم لكن بشرط : \nأي حد هيكفر بعد نزول المائدة، ربنا هيعذبه عذاب شديد جدا؛ لإن همّ إللي طلبوها واشترطوا ..\nوكمان لإن لو ربنا مكنش اشترط عليهم الشرط ده كانوا هيكرروا كل شوية طلب تاني ويقولوا طيب عايزين كذا وكذا و..و ...و.... والطلبات مش هتخلص\n\"قَالَ اللَّهُ إِنِّي مُنَزِّلُهَا عَلَيْكُمْ فَمَن يَكْفُرْ بَعْدُ مِنكُمْ فَإِنِّي أُعَذِّبُهُ عَذَابًا لاَّ أُعَذِّبُهُ أَحَدًا مِّنَ الْعَالَمِينَ\"\n◇السؤال بقى:\n هل ربنا أنزل عليهم المائدة فعلا؟\nالعلماء اختلفوا هل فعلا ربنا أنزل المائدة ولّا لأ،\nفي علماء قالوا إن الحواريين لما سمعوا الوعيد الإلهي خافوا وقالوا لأ مش عايزينها خلاص..\nوفريق ثاني من العلماء قالوا: إن ربنا فعلا نزلها ...\nوهو ده ظاهر القرآن إللي ربنا قال فيه \"إني مُنَزِّلُها عليكم\"، \nومفيش دليل على الرأي الأول\nفالراجح إن ربنا أنزل عليهم المائدة فعلا\nوعلى فكرة قصة المائدة دي مش مذكورة في الإنجيل\nمذكورة في القرآن فقط والنصارى أخذوا القصة من القرآن بعدين،\nوالحواريين كانوا قالوا إنهم هيوصوا الأجيال إللي بعدهم إنهم يتذكروا نعمة ربنا لما أنزل عليهم المائدة، \nوفعلا كانوا بيعملوا كده لحد ما الناس نسيت، ربنا قال:\n\"ومِنَ الَّذِينَ قَالُواْ إِنَّا نَصَارَى أَخَذْنَا مِيثَاقَهُمْ فَنَسُواْ حَظًّا مِّمَّا ذُكِّرُواْ بِهِ \"\nبنو إسرائيل بقى مش عاجبهم عيسى عليه السلام ولا الناس إللي آمنت معاه سواء الحواريين أو عامة الناس إللي اتبعوه عليه السلام،\nخايفين بقى لياخد منهم المُلك واحنا عارفين تاريخهم مع الأنبياء كان عامل إزاي قبل كده\nعملوا إيه بقى مع عيسى عليه السلام\nاحنا عارفين إن الدولة الرومانية هي إللي كانت بتحكم فلسطين في الزمن ده، وفاكرين هيرودس وإللي عمله مع يحيى عليه السلام،\nهيرودس في الزمن ده كان مات، وتولى بعده حاكم روماني كافر،\nفراح اليهود للملك الروماني، وقعدوا يحرّضوه على قتل عيسى عليه السلام\nقالوا له كذبا وبهتانا إن عيسى بيخطط عشان يعمل ثورة عليك وياخد منك الحكم، \nو وجُوده فيه تهديد على مُلكَك، فانت اصلبه واخلص منه، ودمه في رقبتنا ورقبة عيالنا احنا \nوفضلوا وراه يقنعوه إن دي خطط عيسى بن مريم، لحد ما  فعلا الملك الروماني أمر جنوده إنهم يروحوا يقبضوا على عيسى عليه السلام، \nراح الجنود وكانوا عارفين إن عيسى معاه اثنى عشر رجل، إللي همّ الحواريين،\nوصل الجنود لحد باب البيت وهيقتحموا البيت عشان يقبضوا على عيسى عليه السلام\nحصل إيه لعيسى عليه السلام ؟\nوهل فعلا الجنود مسكوه ولّا لأ؟\nده إللي هنعرفه إن شاء الله في الجزء الأخير من سلسة قصص الأنبياء \n♡ملحوظة\nإن شاء الله بعد سلسلة قصص الأنبياء هيكون في سلسلة للسيرة النبوية \nهي هتبقى سلسلة لوحدها عشان السيرة طويلة\nفالسيرة هتكون الجزء الثاني من قصص الأنبياء\n♡#قصص_الأنبياء\n#الحلقة_الستون_والأخيرة\n#مريم_زكريا_الجزء_الجزء_العاشر\n#عيسى_الجزء_السادس_والأخير\nوقفنا المرة إللي فاتت عند الملك الروماني لما أرسل جنوده عشان يقبضوا على عيسى عليه السلام والسبب كان إن اليهود حرّضوه على عيسى عشان شافوا الناس بدأت تُؤمن بيه وخافوا على مُلكُهم وسط الناس؛ لإن عيسى عليه السلام فضحهم وفضح كذبهم وتلاعبهم بالدين ،\n\"ومَكَرُواْ وَمَكَرَ اللَّهُ وَاللَّهُ خَيْرُ الْمَاكِرِينَ\"\nأرسل الملك جنوده للبحث عن عيسى عليه السلام،\nفلما كان الجنود في الطريق، ربنا أوحى لعيسى عليه السلام إنه هيتوفّاه ويرفعه إلى السماء،\nيعني هيرفعه عنده بالنوم مش بالموت، والنوم زي ما انتم عارفين هو \"مَوْتة صغرى\" ،\nأما الموت نفسه بقى فهو \"المَوْتَة الكُبرى\"،\nفربنا أوحى له إنه هينيمه ويرفعه للسماء يقعد فيها لحد ما ييجي الوقت إللي هينزل فيه تاني عشان يكمل حياته على الأرض ويموت الموتة الكبرى زي باقي البشر .\n\"\"إذْ قَالَ اللَّهُ يَا عِيسَى إِنِّي مُتَوَفِّيكَ وَرَافِعُكَ إِلَيَّ وَمُطَهِّرُكَ مِنَ الَّذِينَ كَفَرُواْ \"\nوكان عيسى عليه السلام في بيته وعنده الحواريين، فخرج عليهم بعد ما اغتسل وراسه لسه بتنزّل مية، \nوحكالهم إن الجنود عايزين يقتلوه وإنهم في الطريق،\nوقال لهم : فيكم واحد هيكفر بيّ ١٢ مرة\n☆يعني في واحد منكم الجنود هيمسكوه ويقولوا له: انت من أتباع عيسى..! فهيقول لا أبدا أنا غير مؤمن بيه أصلا!.. \nفهيسيبوه، \nويرجع يؤمن بعيسى عليه السلام تاني، فيمسكوه تاني ويقولوا انت من أتباع عيسى؟! \nفيقول لهم لأ أنا غير مؤمن به.. وهكذا... ١٢ مرة\nهو هنا مش مُظهر الكفر ومُبطن الإيمان زي ما ممكن تتخيلوا إن المعنى كده، لأ،\nده كفر قلبي، يعني بيكفر بعيسى ثم يرجع يؤمن ثم بعدين يكفر تاني وهكذا\nهنا بقى عيسى عليه السلام فهمهم إن ربنا هيرفعه عنده، وان بني إسرائيل هيقتلوا واحد تاني بداله ربنا هيخليه شبه عيسى،\nفسألهم:\nمين فيكم ربنا يخليه شَبَهِي ويُقتل مكاني ويكون رفيقي في الجنة؟\nفشاب صغير قال : \nأنا\nفكأن عيسى عليه السلام أشفق عليه،\nلأنه كان عارف إنهم هيقتلوه لكن مش هيقتلوه قتلة عادية وسريعة..ده قتل عن طريق الصلب،\nيعني يحطوا الرجل على صليب وبعدين يدقوا المسامير في جسد الرجل من عند إيده ورجله عشان يثبّتوه في الصليب،\nفيموت بعد يوم أو أكثر بسبب النزيف وفقدان الدم من جسمه بغزارة زائد، إنه هيكون اتخنق بسبب نقص الأوكسجين في دمه\nتخيلوا يوم كامل إنسان بيتخنق بالبطيء لحد ما يموت.. عذاب فعلا\nفسأل عيسى عليه السلام مرة ثانية: مين ربنا يخليه شبهي ويكون رفيقي في الجنة؟\nفنفس الشاب قال أنا يا نبي الله.. أنا\n!\nفعيسى عليه السلام أعاد السؤال مرة ثالثة وهو بيبص للباقيين، فنفس الشاب قال : أنا! أنا \nفعيسى قال له: خلاص.. انت إللي هتكون مكاني..\nوبالفعل، ربنا غيّر شكل الشاب وخلاه نفس شكل عيسى بالضبط!\nوالحواريون شايفين ومذهولين طبعا.. \n◇ودي كانت الرواية الأولى في قصة إلقاء الشبه على رجل يُقتل مكان عيسى عليه السلام بعد رفعه،\nوالرواية دي قول ابن عباس رضي الله عنه\n◇الرواية التانية بتقول إن في واحد من الحواريين كان منافق وخان عيسى عليه السلام وهو إللي دل الجنود على مكانه قبل ما يوصلوا له ،\nفربنا ألقى عليه شكل عيسى عليه السلام عشان يُقتل مكانه عقابا له..\nواحنا معندناش نص صريح من القرآن والسنة يقول لنا بالظبط إيه إللي حصل، وأنهي رواية من الروايتين دول هم إللي صح\nلكن المؤكد هو إن ربنا ألقى شبَه عيسى عليه السلام على واحد عشان يقتل مكانه ويترفع عيسى للسماء\nوجاءت لحظة رفع عيسى عليه السلام،\nكان في فتحة في سقف بيته عليه السلام،\nفربنا رفعه منها إلى السماء  يوم الجمعة بعد العصر،  والرفع كان رفع كامل من الأرض بالجسد والروح، \nيعني هو لسه عايش لحد دلوقتي وهينزل آخر الزمان ونزوله من علامات الساعة الكبرى إللي هنعرف تفاصيلها إن شاء الله واحنا بنحكي السيرة النبوية،\nوهي دي عقيدتنا كمسلمين في عيسى بن مريم، \nإنه نبي وعبد لله، ولم يُصلب أو يُقتل ، بل رفعه الله إليه\nو أي كلام تاني غير ده في أي عقيدة تانية هو تكذيب لله عز وجل وتكذيب لرسوله ولكتاب،\nوعيسى عليه السلام حاليا في السماء التانية مع ابن خالته يحيى عليه السلام،\nلإن يحيى هو ابن إشياع إللي احنا قلنا عنها في الأول إنها أخت مريم أو خالتها،\nوابن خالة أمي يكون ابن خالتي أنا كمان،\nزي مثلا عم أمي يكون عمي وخال أمي يكون خالي وهكذا\nبعد رفع عيسى عليه السلام دخل الجنود البيت على الحواريين ومعاهم شبيه عيسى عليه السلام، على أساس إننا أخدنا بالرواية الأولى بتاعة الشاب المؤمن الشجاع،\nفأيا كان فالجنود أخدوا الشبيه وراحوا بيه للملك، والملك أمر  بصلبه، واليهود حطوا على رأسه إكليل من الشوك،\nالإكليل إللي هو الطوق إللي بيتحط على الرأس ده وبيكون فيه زهور مثلا،\nاليهود حطّوا بدل الورد شوك في الإكليل .. وصلبوه..\nوقعدوا يقولوا احنا قتلنا عيسى وصلبناه،\n\"وَقَوْلِهِمْ إِنَّا قَتَلْنَا الْمَسِيحَ عِيسَى ابْنَ مَرْيَمَ رَسُولَ اللَّهِ وَمَا قَتَلُوهُ وَمَا صَلَبُوهُ وَلَٰكِن شُبِّهَ لَهُمْ\"\nوطبعا لا قتلوه ولا صلبوه ..لأن إللي اتقتل ده كان شبيه عيسى عيسى عليه السلام\n \n\"وَمَا قَتَلُوهُ يَقِينًا ۩ بَل رَّفَعَهُ اللَّهُ إِلَيْهِ ۚ وَكَانَ اللَّهُ عَزِيزًا حَكِيمًا \"\nوحصل الاختلاف بعد رفع عيسى عليه بين الناس إللي كانت متبعة عيسى عليه السلام ... فرقة قالت :\nإللي كان بيننا ده هو الله .. كان موجود معانا فترة معينة وبعدين رجع للسماء،\nوفرقة تانية قالت:\nلأ، إللي كان بيننا ده هو ابن الله قعد معانا فترة وبعدين الله رفعه عنده فوق،\nوفرقة ثالثة قالت:\nلأ، إللي كان بيننا ده هو عبد الله ورسوله.. قعد معانا فترة وبعدين ربنا رفعه عنده.. بسيطة أهه والله وتمشي\n \nلكن طبعا بنو إسرائيل كفرهم مالهوش حدود، \nفالفرقة الأولى والتانية الكافرتَيْن قعدوا يُقتّلوا في الفرقة التالتة المسلمة المؤمنة بنبوة المسيح وعبوديته لله عز وجل،\nقعدوا يقتلوا فيهم لحد ما مبقاش من المؤمنين إللي كانوا على التوحيد إلا قلة قليلة جدا\n☆الموضوع سهل وبسيط ومفهوش أي تعقيد، ومنطقي بالنسبة للعقل السليم اللي الهوى مش بيتحكم فيه \nطب أومال بنو إسرائيل ليه عقَّدوا المسألة كده\nبسبب إعراضهم عن الحق ، واتباع الظن والهوى\n\"وَإِنَّ الَّذِينَ اخْتَلَفُوا فِيهِ لَفِي شَكٍّ مِّنْهُ ۚ مَا لَهُم بِهِ مِنْ عِلْمٍ إِلَّا اتِّبَاعَ الظَّنِّ ۚ\"\nخلونا نشوف مع بعض كام سؤال كده، مفيش أي واحد نصراني يقدر يجاوب على أي واحد فيهم إجابة منطقية عقلية \n◇أولا:\nالنصارى بيقولوا إن عيسى هو ابن الله ماشي كده..وده معناه إن الله يحب يكون عنده أولاد عشان كده عنده ولد اسمه عيسى صح؟\nطيب لما الله بيحب يكون عنده أولاد ليه معندهوش غير ولد واحد..يعني هو بيحب يكون عنده أولاد ليه يكتفي بواحد بس؟\nليه ميكنش عنده عشرة أو عشرين أو...أو..مادام فكرة وجود الولد عند الله موجودة ليه يكتفي بولد واحد بس وكمان ليه ميكنش عنده ولد وبنت \n◇ثانيا:\nالنصارى بيقولوا إن الله أرسل عيسى للأرض عشان يُصلَب عشان يطهَّر البشر من الخطيئة إللي بدأت مع آدم والدّنس بتاعها مستمر كل ده، \nيعني بيقولوا إن ربنا نزّل ولده الوحيد للأرض عشان يتصلب بسبب غلطة عملها آدم..\nطيب ليه عيسى هو إللي يتصلب؟ ما يُصلب آدم إللي كان السبب في الموضوع من الأول\nثم يعني الله الإله الحق المستحق للعبادة الحكيم القدير الرحيم العدل معندهوش أي وسيلة ولا طريقة تانية يطهر بيها العباد من الخطيئة إلا إنه ينزل ابنه الوحيد يتصلب مكان واحد تاني، وبالنيابة عن باقي البشرية كلها إللي هتتبعه وإللي لسه هترتكب خطايا الله أعلم هتكون إيه \nيعني مكنش ممكن يقول بدل ده مثلا: أنا منعتكم تشربوا الماء البارد عشان عندكم خطيئة؟ \nولّا ماتقعدوش في الظل ولّا ماتغطوش رؤوسكم من الشمس،؟ أي عقوبة يعني \nممكن يردوا ويقولوا: لأ هو مش بيعاقبهم هو بيعمل كده من شدة رحمته بالبشرية\nيعني هو رحمته واسعة جدا أهه، صح؟\nطب إزاي إللي بالرحمة الواسعة دي يقسو على شخص بالمنظر ده وهو معملش حاجة مؤذية عشان يرحم ناس تانية مؤذية\nيعني من رحمته الواسعة إن ابنه الوحيد البريء الطاهر المظلوم هو إللي يتعاقب بدل الناس دي كلها؟\nهل ده العدل إللي بتتمنوه من الإله إللي بتعبدوه؟\nيعني هل في حد يقبل على نفسه إن حد غيره هو إللي يغلط وبعدين تقوم انت تدخل السجن مكانه أو تنضرب مكانه أو تتعذب مكانه؟\nده إيه المنطق العجيب ده\nساء ما يحكمون، وسبحان الله عما يصفون\n◇ثالثا:\nالنصارى بتقول إن عيسى إله، وإن الله -إللي هو الأب- إله برده، \nوطبعا الإله يعني يفعل ما يشاء وقتما يشاء.. \nطيب لو عيسى كان عايز شخص يموت النهاردة ، و الله يريده حي ما يموتش دلوقتي ..كلام مين إللي يمشي\nلو قالوا الرب ..يبقى عيسى مش إله.. لإن في واحد بيمَشِّي كلامه عليه، ومن صفة الإله إنه يفعل ما يشاء \nولو قالوا عيسى إللي كلامه يتنفذ، يبقى الرب بتاعهم مش إله \nوطبعا مينفعش نقول كلامهم كلهم يتنفذ في نفس الوقت، لإن إزاي يقتلوه ويسيبوه عايش في نفس الوقت؟ \nيبقى ميت وحي في نفس الوقت \n\"لَوْ كَانَ فِيهِمَا آلِهَةٌ إِلَّا اللَّهُ لَفَسَدَتَا ۚ فَسُبْحَانَ اللَّهِ رَبِّ الْعَرْشِ عَمَّا يَصِفُونَ\"\nولّا واحد هيقتله النهاردة، والتاني يُحييه بكرة، ثم يرجع الأولاني يقتله تاني، وهكذا...! \n\"أفحسبتم أنما خلقناكم عَبثًا\"\nوعلى فكرة بقى في الأناجيل الأربعة الموجود حاليا إللي هي كمان متحرفة أصلا مفيش أي حاجة فيهم بتقول إن عيسى عليه السلام قال: \nأنا ابن الله\nيعني رغم إنهم حرّفوا الأناجيل، لم يضيفوا الكلام ده فيها، واخترعوا القصة دي منهم لنفسهم كده وألزموا أتباعهم بيها ، مع إن أتباعهم مش شايفينها في الأناجيل! \nدي عقيدة يا جماعة مش حكم فقهي، إزاي تتبعوا ناس في كلام مش مكتوب في الكتاب إللي انتوا معتقدين إنه من عند ربكم\nضلال مبين والعياذ بالله\nوعيسى عليه السلام نفسه بريء من الكلام ده،\nويوم القيامة لما ربنا هيسأله عليه السلام هل إنت قلت للناس إنهم يعبدوك وإنك إله من دوني؟ \n\"وَإِذْ قَالَ اللَّهُ يَا عِيسَى ابْنَ مَرْيَمَ أَأَنتَ قُلْتَ لِلنَّاسِ اتَّخِذُونِي وَأُمِّيَ إِلَٰهَيْنِ مِن دُونِ اللَّهِ\"\nهيرد عيسى عليه السلام ويقول أنا مقلتش للناس غير إللي انت أمرتني بيه يارب،وإنت سامع وشايف مافيش حاجة بتخفى عنك، \n\"قَالَ سُبْحَانَكَ مَا يَكُونُ لِي أَنْ أَقُولَ مَا لَيْسَ لِي بِحَقٍّ ۚ إِن كُنتُ قُلْتُهُ فَقَدْ عَلِمْتَهُ ۚ\"\nما قلت لهم إلا إنهم يعبدوك ولا يشركوا بيك أي شيء أو أي حد\n \"مَا قُلْتُ لَهُمْ إِلَّا مَا أَمَرْتَنِي بِهِ أَنِ اعْبُدُوا اللَّهَ رَبِّي وَرَبَّكُمْ ۚ وَكُنتُ عَلَيْهِمْ شَهِيدًا مَّا دُمْتُ فِيهِمْ ۖ فَلَمَّا تَوَفَّيْتَنِي كُنتَ أَنتَ الرَّقِيبَ عَلَيْهِمْ ۚ \"\nآدي يا جماعة عيسى ابن مريم وعقيدته عن ربه عز وجل، فماذا بعد الحق إلا الضلال\nوأهل الكتاب هيؤمنوا بعيسى عليه السلام بإنه نبي مرسل من عند ربنا لما ينزل آخر الزمان بعد خروج المسيح الدجال ومش هينفعهم إيمانهم ساعتها لأنهم هيكونوا من أتباع الدجال وهيُقتلوا بأيد المؤمنين، أما إللي مش هيقتلوا فهيؤمنوا بيه ويبقوا من أتباعه،\nوالأمر فيه تفصيل، إن شاء الله هتعرفوا التفصيل في سلسلة علامات الساعة لما تقرأوا السيرة،\nربنا بيقول:\n\"وَإِن مِّنْ أَهْلِ الْكِتَابِ إِلَّا لَيُؤْمِنَنَّ بِهِ قَبْلَ مَوْتِهِ ويوم القيامة يكون عليهم شهيدا\"\nونزول عيسى عليه السلام هيكون في آخر الزمان بعد خروج المسيح الدجال:\n\"وَإِنَّهُ لَعِلْمٌ لِّلسَّاعَةِ\"\nهينزل في شرق دمشق ، وهيكسر الصليب ويقتل الخنزير ويقتل المسيح الدجال،\nوهيقعد في الأرض أربعين سنة وبعدها يموت الموتة الكبرى، ويصلِّي عليه المسلمون ويدفنوه\n☆قبل ما نختم.. في سؤال مهم لكل مسلم ومسلمة..\nلو في واحد أو واحدة عمالين يشتموا أمكم أو أبوكم، هتعملوا معاهم إيه؟\nهل علاقتكك بيهم هتكون علاقة حب ومودة؟ \nولّا هتوقفوهم عند حدهم وتقولوا لهم إن مينفعش تشتموا أهلي! \nطب ولو طنشوا كلامكم وكملوا شتم لأهللكم الكرام؟ \nهل طبيعي إنكم تكملوا علاقة حب وانغماس معاهم في علاقة وطيدة كلها مودة وألفة؟ \nطب هل طبيعي إننا نقول لهم كل شتيمة وانتم بخير؟\nطيب شوفوا الحديث ده كده ، يوجع قلب أي مسلم والله.. لمن كان له قلب..  \nربنا بيقول في حديث قدسي:\n\"شتمني ابن آدم وما ينبغي له أن يشتمني،\nقال: اتخذ الله ولدا وأنا الله الأحد الصمد لم ألد ولم أولد ولم يكن له كفوا أحد\"\nتخيل كده واحد بيشتم ربنا عز وجل، واحنا نروح نقول له شاطر.. استمر.. كل  شتيمة وانت بخير.. كل سنة وانت طيب وبتشتم في ربي\nهي كده والله ومالهاش معنى إلا كده، لما يكون فيه مسلمين بيهنوا النصارى بعيدهم ويقولوا لهم كمان كل سنة وانتم طيبين!..\nكإنهم بيقولوا لهم: كل سنة وإنتم مستمرين في شتيمة ربنا، كل سنة وانتم مستمرين في كفركم بالله ومستمرين على المنكر..\nسامعاكم ياللي هتقولوا لي بطلوا تشدد وفتنة طائفية\nوهتقولوا كمان ده ربنا وصانا عليهم و ده من الإحسان ليهم إللي ربنا أمرنا به، \nوكمان ينفع إن الرجل يتزوج واحدة نصرانية، يعني معقولة في عيدها مش هيقول لها كل سنة وإنتِ طيبة وهي مراته \nطيب تعالوا يا جماعة كده نعرف ديننا بيقول لنا إيه في علاقتنا مع أهل الكتاب، عشان نعرف بس أد إيه إننا خالطين الأوراق في بعض\nعندنا حاجتين : البِرّ والمودة.. \n◇البر ده يعني إيه \nيعني بتعمل عمل خير معين، بجسمك فقط وجوارحك، لكن مشاعر قلبك ملهاش دخل فيه،\nطبعا كلنا عارفين قصة البَغِي إللي دخلت الجنة بسبب كلب سقته\nده اسمه بر ، يعني وَصّلت الخير لكائن حي، بغض النظر أنا بحبه ولّا بكرهه.. ماشي كده\nيعني لو شوفت واحد نصراني مظلوم واجب علينا إننا ننصره ،\nلو شفنا واحدة نصرانية محتاجة مساعدة نساعدها، نواسي أهل الكتاب في المصائب ونعزيهم لو مات لهم ميت،\nبس طبعا من غير ما نقول على الميت بتاعهم \"الله يرحمه\" ولا الكلام ده خالص، لإن الدعاء بالرحمة خاص بمن مات على الإيمان فقط \nلإن ربنا بيقول :\n\"مَا كَانَ لِلنَّبِيِّ وَالَّذِينَ آمَنُوا أَن يَسْتَغْفِرُوا لِلْمُشْرِكِينَ وَلَوْ كَانُوا أُولِي قُرْبَىٰ مِن بَعْدِ مَا تَبَيَّنَ لَهُمْ أَنَّهُمْ أَصْحَابُ الْجَحِيمِ\"\nوبالتالي أي عمل فيه خير وبر وإحسان وإنصاف ليهم مفيهوش أي مشكلة\nوربنا قال لنا ده بوضوح :\n\" لا يَنْهَاكُمُ اللَّهُ عَنِ الَّذِينَ لَمْ يُقَاتِلُوكُمْ فِي الدِّينِ وَلَمْ يُخْرِجُوكُمْ مِنْ دِيَارِكُمْ أَنْ تَبَرُّوهُمْ وَتُقْسِطُوا إِلَيْهِمْ إِنَّ اللَّهَ يُحِبُّ الْمُقْسِطِينَ \"\nبالعكس ده بيكون دعوة حلوة للإسلام بأخلاق الإسلام،\nلكن في نفس الوقت ميكونش في ميوعة في التعامل مع دينهم وعقيدتهم\n◇أما المودة بقى دي مشاعر قلبية.. مينفعش تكون موجودة من المسلم لواحد نصراني بيسب الله عز وجل ويكفر بيه ليل نهار.. \nخصوصا لو مودتك دي اترجمت لكلام حقيقي وأفعال ظاهرة فكده كإنك تشجعه على إللي بيعتقده من الكفر و الضلال \nوده عكس الإيمان..\nورسول الله ﷺ قال:\n\"إِنَّ أَوْثَقَ عُرَى الْإِيمَانِ: أَنْ تُحِبَّ فِي اللهِ، وَتُبْغِضَ فِي اللهِ\"\nالنصارى دول كفار صح ..ولا فيه اعتراض على دي كمان لا سمح الله\nأكيد كلنا عقيدتنا إن عقيدة النصارى كفر.. \nوحافظين قول الله الواضح جدا :\n\"لَقَدْ كَفَرَ الَّذِينَ قَالُوا إِنَّ اللَّهَ هُوَ الْمَسِيحُ ابْنُ مَرْيَمَ \"\n\"لقد كفر الذين قالوا إن الله ثالث ثلاثة\"\nالكفار دول على منكر... فأنا بقى بدل ما أدعوهم ليل نهار لترك المنكر ده والرجوع للحق، أروح أهنيهم عليه\n◇طيب وبالنسبة للرجل إللي بيتزوج واحدة نصرانية إيه نظامه\nالزواج من نساء أهل الكتاب مش مفتوح على مصراعيه كده زي زواج المسلم من المسلمة،\nالزواج ده له شروط، ده غير إن حتى بعد الزواج كمان مينفعش إنها تُظهر دينها كده زي المسلمين،\nوكمان يجب على الزوج إنه يأمرها بالمعروف وينهاها عن المنكر برده مش سايبها كده ،\nوبالتالي هو مش بيتزوجها وهو بيقرها على إللي هي بتعمله وبيهنّيها عليه كمان،\nده غير إن المحبة بينهم بتكون محبة طبيعية غريزية ،\nزي محبة الأكل والشرب مثلا، وزي ما كان رسول الله ﷺ  بيحب أبو طالب مع إنه كافر،\nفالمحبة الفطرية دي إللي بتكون بين الأهل بطبيعة الحال غير المحبة الدينية، \nممكن أكره حد في الله لإنه من أهل المجاهرة بالمعاصي أو كافر،\nلكن في نفس الوقت بشفق عليه وبحبه لإنه طيب وإيده سخية مثلا على الفقراء ومعاملته حلوة لأهل الحي و...و...  يعني حب طبيعي لحد بيعمل خير وسايب أثر طيب في النفوس من حسن العشرة والأخلاق، \nلكن في نفس الوقت قلبي كارهه في الله للمعاصي والمجاهرة أو الكفر إللي بيعمله،\nفمفيش مشكلة إن تجتمع العداوة الدينية مع المحبة الفطرية الطبيعية \nزي الدواء احنا بنحبه عشان بيكون سبب إنه يشفينا، وفي نفس الوقت بنكرهه عشان طعمه وحش\nحصل إيه بقى لبني إسرائيل بعد صلبهم لعيسى عليه السلام\nقعدوا يضطهدوا أتباع عيسى عليه السلام المؤمنين بيه، ويقتلوهم ويعذِّبوهم زي ما قلنا،\nوعملوا ثورة في القدس عشان يستعيدوا الحكم الذاتي إللي كان معاهم زمان قبل الحكم الروماني لو تفتكروا،\nجالهم بقى قائد روماني اسمه تِيتوس عمل فيهم مجزرة\nحاصر القدس فترة.. فاليهود استسلموا ..\nفدخل تيتوس المدينة وجمع اليهود وأمرهم إنهم يقتلوا بعض\nوإللي هينجو من المقتلة دي هو إللي تيتوس هيسيبه يكمل حياته ومش هيقتله،\nوفعلا بدأوا يقتلوا في بعض ...رجال ونساء وأطفال\nولم ينجوا من المجزرة دي غير الشريد، يعني الشخص إللي مكنش موجود في المدينة في الوقت ده هو إللي نجى من المجزرة دي\nفاتبقى شوية قليلين جدا من اليهود، حبة هنا على حبة هنا، \nودمر تيتوس المسجد الأقصى \nوتفرق الحواريون في الأرض عشان يدعوا لدين المسيح وحصلت أحداث كتير بعد كده مش هنقدر نشرحها هنا\nعيسى عليه السلام لما كان بيدعو في بني إسرائيل قبل ما يتوفاه الله كان بلّغ بني إسرائيل إن في رسول هييجي من بعده اسمه أحمد:\n\"وَمُبَشِّرًا بِرَسُولٍ يَأْتِي مِن بَعْدِي اسْمُهُ أَحْمَدُ\"\nوصفة الرسول أحمد ده موجودة عندهم في التوراة والإنجيل\n\"الَّذِينَ يَتَّبِعُونَ الرَّسُولَ النَّبِيَّ الْأُمِّيَّ الَّذِي يَجِدُونَهُ مَكْتُوبًا عِندَهُمْ فِي التَّوْرَاةِ وَالْإِنجِيل\"\nمين النبي أحمد إللي عيسى عليه السلام بشّر به ؟\nهو محمد رسول الله ﷺ خاتم الأنبياء والمرسلين والرحمة المُهداة للعالمين\nولإن هو خاتم الأنبياء وربنا أرسله للعالمين من الجن والإنس، فقصته أطول قصة في قصص الأنبياء،\nلأن عندنا تفاصيل بأحداث حياته من البداية وحتى وفاته،  وربنا حفظ لنا تفاصيل حياته كلها عشان نتعلم منها كل إللي ممكن نحتاجه ليوم الدين\nعشان كده هنخلي قصة النبي محمد ﷺ في سلسلسة جديدة هي سلسلة \"السيرة النبوية\"\nوهي سلسلة هتعرفكم معلومات كتير جدا عن رسول الله ﷺ وعن الصحابة وعن الإسلام وعن باقي قصص القرآن والحديث النبوي وعلامات الساعة الصغرى والكبرى وغيرها وغيرها من الأحداث\n♡وأخيرا:\n جزاكم الله خيرا على الاستمرار في القراءة لحد آخر جزء،، ولا تنسونا من صالح دعائكم\n♡تمت  قصص الأنبياء"}]);
